// C/P Practice Test flashcards: original stand-alone cards that teach what the Chem/Phys questions of AAMC Practice
// Exams 1, 3, 4, 5 and 6 need (the pe1-cp … pe6-cp cards of data/qb-aamc-fl.js). TODAY's C/P flashcard step uses only
// these cards (masteryFlashPool in js/mastery.js).
// Every card names, in `from`, the Practice Exam card(s) whose question needs it; `aamc` and `disc` come from that card.
// Original wording, numbers and compounds only: no AAMC passage, question, number or answer choice is reproduced.
// Format: {id, s: topic tag, disc, aamc, q, choices: [4], ans: 0-3, exp, from: [src, …], how: {ask, know, steps, trap}, teach}
// One card per method: a card lists in `from` every spec item (and so every question) it prepares for, across the
// exams; the whole deck stays at 250 cards or fewer (tools/test-cp-test-cards.cjs).
const CP_TEST_CARDS = [
  // ── Practice Exam 1 · Chem/Phys ──
  {"id":"cpt-pe1-03a","s":"Separations & Lab Techniques","disc":"organic_chem","aamc":"5C","skill":"SIRS 4","from":["pe1-cp:3#1","pe1-cp:1#1"],"q":"A TLC baseline is 1.5 cm above the plate's lower edge. Measured from that edge, the solvent front is at 9.5 cm and a spot's center is at 5.5 cm. What is the retention factor (Rf)?","choices":["0.42","0.50","0.58","2.0"],"ans":1,"exp":"**Rf = spot distance ÷ solvent-front distance, both from the baseline.** Spot: 5.5 − 1.5 = 4.0 cm. Front: 9.5 − 1.5 = 8.0 cm. Rf = 4.0 ÷ 8.0 = **0.50**.","how":{"ask":"Measure both distances from the baseline, then divide.","know":"**Rf = distance moved by the compound ÷ distance moved by the solvent front**, both measured from the **baseline** where the sample was spotted. Rf is between 0 and 1.","steps":[{"text":"The distances are given from the edge, but the sample started at the baseline.","hl":"baseline is 1.5 cm above the plate's lower edge","fig":"cpt-tlc-plate"},{"text":"Subtract the baseline from both readings.","calc":["spot: 5.5 − 1.5 = **4.0 cm**","front: 9.5 − 1.5 = **8.0 cm**"]},{"text":"Divide.","calc":["Rf = 4.0 ÷ 8.0 = **0.50**"]},{"text":"0.58 skips the baseline (5.5 ÷ 9.5), 0.42 subtracts it from only the spot, and 2.0 is inverted.","strike":["0.58","0.42","2.0"]},{"text":"Answer: 0.50."}],"trap":"Dividing the raw readings (5.5 ÷ 9.5 = 0.58): both distances must start at the baseline."},"teach":[{"text":"First, **find every number** and what it means.","marks":[{"t":"1.5 cm","note":"where the sample started"},{"t":"9.5 cm","note":"solvent front, from the edge"},{"t":"5.5 cm","note":"spot, from the edge"}]},{"text":"**Start at the baseline.** The race starts where the sample was spotted, not at the plate's edge.","calc":["spot: 5.5 − 1.5 = 4.0 cm","front: 9.5 − 1.5 = 8.0 cm"]},{"text":"**Divide spot by front.**","calc":["Rf = 4.0 ÷ 8.0 = 0.50"]},{"text":"**Also:** on silica, the compound with the strongest polar groups (O–H or N–H first) has the smallest Rf."},{"text":"**Also:** a low Rf means strong binding to the stationary phase; a high Rf means the compound prefers the mobile phase."},{"text":"**Also:** only N–H, O–H and F–H donate hydrogen bonds; C=O and ether oxygens can only accept them."},{"text":"**Also:** in chromatography, Rf is characteristic of the compound under fixed conditions; spot size only reflects how much was applied."},{"text":"**Also:** every Rf lies between 0 and 1; a larger value means the ratio is inverted."},{"text":"**Rule to reuse:** Rf = (spot − baseline) ÷ (front − baseline), and it always falls between 0 and 1."}]},
  {"id":"cpt-pe1-02a","s":"Research Design & Reasoning","disc":"organic_chem","aamc":"5C","skill":"SIRS 3","from":["pe1-cp:2#1"],"q":"A team concludes that amino acids arose on the primitive Earth, since passing sparks through methane and ammonia gave them in the lab. The argument requires that:","choices":["those gases were present then.","the yield exceeded half the methane.","the products were optically pure.","sparks speed up every reaction."],"ans":0,"exp":"A lab synthesis shows what **can** happen. To conclude it **did** happen on the early Earth, the **starting materials and conditions** (here methane, ammonia and electrical discharge) must have existed then. Yield, purity and a claim about all reactions do not bear on that.","how":{"ask":"Find the unstated premise that must be true for the lab result to support the historical claim.","know":"• **Assumption**: a premise the conclusion needs but does not state; if it were false, the conclusion would fail.\n• A lab model of a past event supports the claim only if its **inputs and conditions** existed at that time.","steps":[{"text":"The conclusion is about the early Earth; the evidence is from a lab.","hl":"amino acids arose on the primitive Earth"},{"text":"Test each choice: if it were false, would the argument fail?","calc":["gases absent then → the lab result says nothing about then → fails","low yield → some still formed → stands"]},{"text":"Yield, optical purity and all reactions are not needed for the conclusion.","strike":["the yield exceeded half the methane.","the products were optically pure.","sparks speed up every reaction."]},{"text":"Answer: the gases must have been present on the early Earth."}],"trap":"Choosing a detail about the experiment's quality; the gap is between the lab and the early Earth."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"on the primitive Earth","note":"the conclusion"},{"t":"in the lab","note":"the evidence"},{"t":"requires","note":"find the assumption"}]},{"text":"**Split conclusion from evidence.** The evidence is a lab result; the conclusion is about the past."},{"text":"**Bridge the gap.** For the lab to stand in for the early Earth, the same ingredients had to be there."},{"text":"**Negate to test.** If the gases were absent, the argument collapses, so that is the assumption.","calc":["negate the choice → does the conclusion fail?"]},{"text":"**Also:** an assumption is the unstated premise whose denial would break the conclusion."},{"text":"**Rule to reuse:** a lab model supports a claim about the past only if its starting materials and conditions existed then."}]},
  {"id":"cpt-pe1-04e","s":"Reaction Mechanisms","disc":"organic_chem","aamc":"5C","skill":"SIRS 4","from":["pe1-cp:4#1","pe1-cp:4#3","pe1-cp:4#4","pe1-cp:4#2"],"q":"Which statement about the acid-catalyzed dehydration of 1-methylcyclopentanol is true?","choices":["One water is lost, via a carbocation","Two waters are lost in one step","The alkene geometry is set by the alcohol","The C–H bond breaks before the C–O bond"],"ans":0,"exp":"The OH is protonated and leaves as **one water molecule**, giving a **planar carbocation**; then H⁺ is lost from a neighboring carbon. Because the flat cation forgets the alcohol's 3D arrangement, the reaction is **not stereospecific**, and the C–O bond breaks first (it is E1, not a concerted E2).","how":{"ask":"Judge each statement against the E1 mechanism: what leaves, in what order, through what intermediate.","know":"• **E1 dehydration**: ROH + H⁺ → ROH₂⁺ → **R⁺ + H₂O** (one water) → alkene + H⁺.\n• The C–O bond breaks **first**; the C–H bond breaks last.\n• The carbocation is planar, so the alcohol's geometry is lost: **not stereospecific**.","steps":[{"text":"Write the E1 steps for this tertiary alcohol.","hl":"acid-catalyzed dehydration","calc":["R–OH + H⁺ → R–OH₂⁺","R–OH₂⁺ → **R⁺ + H₂O**","R⁺ → alkene + H⁺"]},{"text":"Only one water molecule leaves, and the steps are separate, not one concerted step.","strike":["Two waters are lost in one step"]},{"text":"The planar cation does not remember the alcohol's arrangement, so the alcohol does not set the geometry.","strike":["The alkene geometry is set by the alcohol"]},{"text":"Water leaves before H⁺ is removed, so the C–O bond breaks first.","strike":["The C–H bond breaks before the C–O bond"]},{"text":"Answer: one water is lost, via a carbocation."}],"trap":"Treating dehydration like E2 (one step, stereospecific): with acid and heat, alcohols go through a carbocation."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"acid-catalyzed dehydration","note":"E1"},{"t":"1-methylcyclopentanol","note":"tertiary alcohol"}]},{"text":"**Count the waters.** One OH leaves as one H₂O."},{"text":"**Order the bonds.** C–O breaks to make C⁺; the C–H breaks after.","calc":["C–O first → C⁺ → C–H last"]},{"text":"**Flat cation, no memory.** The planar C⁺ can lose an H from either side, so the starting geometry does not carry over."},{"text":"**Also:** in E1, the C=C always forms between the cationic carbon and a carbon directly bonded to it."},{"text":"**Also:** a direct E1 alkene always has the former C–OH carbon in its C=C."},{"text":"**Also:** E1 through a planar carbocation gives both E and Z alkenes, with the more stable E usually major."},{"text":"**Also:** tertiary alcohols dehydrate most easily because they form the most stable carbocation; primary alcohols dehydrate slowest."},{"text":"**Rule to reuse:** acid-catalyzed dehydration loses one water through a carbocation, so it is stepwise and not stereospecific."}]},
  {"id":"cpt-pe1-05a","s":"Amino Acids & Proteins","disc":"organic_chem","aamc":"5C","skill":"SIRS 1","from":["pe1-cp:5#1"],"q":"The activated carboxyl group of glycine reacts with the amino group of valine, releasing one water molecule. Which linkage forms?","choices":["Amide","Ester","Anhydride","Ether"],"ans":0,"exp":"Carboxyl + **amine** → **amide** (a peptide bond), with loss of H₂O. Carboxyl + alcohol gives an ester; carboxyl + carboxyl gives an anhydride; an ether needs two alcohols.","how":{"ask":"Name the bond made when a carboxyl group condenses with an amine.","know":"• **Condensation** joins two groups and releases H₂O.\n• RCOOH + R′NH₂ → **amide** (RCONHR′); RCOOH + R′OH → ester; RCOOH + RCOOH → anhydride.\n• Between amino acids the amide is the **peptide bond**.","steps":[{"text":"The partner is the amino group, an amine.","hl":"amino group of valine"},{"text":"Ester and ether need an alcohol O; an anhydride needs a second carboxyl group.","strike":["Ester","Ether","Anhydride"]},{"text":"Answer: an amide (peptide) bond."}],"trap":"Choosing ester because water is lost; esters also lose water, but only when the partner is an alcohol."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"carboxyl group","note":"acyl donor"},{"t":"amino group","note":"N nucleophile"},{"t":"releasing one water","note":"condensation"}]},{"text":"**Match the partner.** The nucleophile here is nitrogen, from the amine."},{"text":"**Build the bond.**","calc":["R–COOH + H₂N–R′ → R–CO–NH–R′ + H₂O"]},{"text":"**Rule to reuse:** carboxyl + amine → amide (peptide bond); carboxyl + alcohol → ester."}]},
  {"id":"cpt-pe1-06a","s":"Reaction Mechanisms","disc":"organic_chem","aamc":"5D","skill":"SIRS 2","from":["pe1-cp:6#1"],"q":"Which statement gives the order of SN2 reaction rates for alkyl halides with the same leaving group?","choices":["Methyl fastest, tertiary slowest","Tertiary fastest, methyl slowest","Secondary fastest, methyl slowest","Primary fastest, tertiary slowest"],"ans":0,"exp":"SN2 needs **backside attack** on the carbon bearing the leaving group. Each added alkyl group crowds that side: **methyl > 1° > 2° ≫ 3°** (tertiary essentially does not react by SN2).","how":{"ask":"Rank substrates by how crowded the backside of the reacting carbon is.","know":"• **SN2**: one step, the nucleophile attacks opposite the leaving group.\n• Steric order: **methyl > primary > secondary ≫ tertiary**.\n• The reverse order (3° fastest) belongs to SN1, which goes through a carbocation.","steps":[{"text":"SN2 rate depends on access to the carbon's backside.","hl":"order of SN2 reaction rates","fig":"cpt-sn2-backside"},{"text":"Tertiary-first is the SN1 order; secondary-first fits neither.","strike":["Tertiary fastest, methyl slowest","Secondary fastest, methyl slowest"]},{"text":"Primary is fast but methyl, with no alkyl groups, is faster still.","strike":["Primary fastest, tertiary slowest"]},{"text":"Answer: methyl fastest, tertiary slowest."}],"trap":"Using carbocation stability (3° > 2° > 1°); that ranks SN1 rates, not SN2."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"SN2","note":"backside attack, one step"},{"t":"same leaving group","note":"only sterics differ"}]},{"text":"**Picture the attack.** The nucleophile must reach the carbon from behind the leaving group."},{"text":"**Count the blockers.** Each alkyl group on that carbon gets in the way.","calc":["CH₃–X: 0 → fastest","1°: 1","2°: 2","3°: 3 → no SN2"]},{"text":"**Also:** SN2 slows with crowding at the carbon being attacked (methyl > 1° > 2°, no 3°), not at the leaving group."},{"text":"**Rule to reuse:** SN2 rates run methyl > 1° > 2° ≫ 3°, the reverse of SN1."}]},
  {"id":"cpt-pe1-07b","s":"Reaction Mechanisms","disc":"organic_chem","aamc":"5D","skill":"SIRS 2","from":["pe1-cp:7#2","pe1-cp:7#1","pe1-cp:7#3"],"q":"3,3-Dimethylbutan-2-ol reacts with HBr. Which product can form without a methyl shift in the carbocation?","choices":["2-Bromo-3,3-dimethylbutane","2-Bromo-2,3-dimethylbutane","2,3-Dimethylbut-2-ene","2,3-Dimethylbut-1-ene"],"ans":0,"exp":"Loss of water from C2 leaves a **secondary cation on C2**. Br⁻ adding there gives **2-bromo-3,3-dimethylbutane** directly. C3 is quaternary (no H), so a **1,2-methyl shift** from C3 makes a 3° cation at C3; that cation gives 2-bromo-2,3-dimethylbutane, 2,3-dimethylbut-2-ene and 2,3-dimethylbut-1-ene.","how":{"ask":"Find the product whose new group sits on the carbon that held the OH, with the carbon skeleton unchanged.","know":"• C⁺ forms where the OH was; Br⁻ there = direct product.\n• A methyl shift moves C⁺ to the next carbon and rearranges the skeleton (the methyl changes carbons).\n• Products with Br on a carbon that never held the OH, a C=C that does not include that carbon, or a changed branching pattern come from the shifted cation.","steps":[{"text":"The OH is on C2; C3 carries two methyls and no H.","hl":"3,3-Dimethylbutan-2-ol"},{"text":"Direct path: Br⁻ adds to C2, keeping both methyls on C3.","calc":["CH₃–CH(Br)–C(CH₃)₂–CH₃ = **2-bromo-3,3-dimethylbutane**"]},{"text":"A 2,3-dimethyl skeleton means one methyl moved from C3 to C2.","strike":["2-Bromo-2,3-dimethylbutane","2,3-Dimethylbut-2-ene","2,3-Dimethylbut-1-ene"]},{"text":"Answer: 2-bromo-3,3-dimethylbutane."}],"trap":"Choosing an alkene because elimination seems \"direct\"; here every listed alkene has the 2,3-dimethyl skeleton of the shifted cation."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"3,3-Dimethylbutan-2-ol","note":"OH on C2, quaternary C3"},{"t":"HBr","note":"cation path"},{"t":"without a methyl shift","note":"direct product"}]},{"text":"**Place the cation.** C⁺ forms on C2, where the OH was."},{"text":"**Compare skeletons.** Before the shift: two methyls on C3. After: one on C2 and one on C3.","calc":["3,3-dimethyl → unshifted","2,3-dimethyl → shifted"]},{"text":"**Pick the unshifted one.** Br on C2 with the 3,3-dimethyl skeleton."},{"text":"**Also:** a carbocation shifts H or CH₃ from a neighboring carbon whenever that makes a more stable cation."},{"text":"**Also:** a new group on a carbon that never held the leaving group is the fingerprint of a carbocation rearrangement."},{"text":"**Rule to reuse:** a product whose groups or branches moved to a carbon that never held the OH came from a rearranged cation."}]},
  {"id":"cpt-pe1-08d","s":"Separations & Lab Techniques","disc":"organic_chem","aamc":"5C","skill":"SIRS 2","from":["pe1-cp:8#3","pe1-cp:8#1","pe1-cp:8#2"],"q":"A mixture of pent-1-ene, 1-chloropentane and pentan-1-ol is run on a nonpolar gas chromatography column. In what order do they reach the detector?","choices":["Alkene, then chloride, then alcohol","Alcohol, then chloride, then alkene","Chloride, then alkene, then alcohol","Alkene, then alcohol, then chloride"],"ans":0,"exp":"Lowest boiling point first. Pent-1-ene has only London forces (bp ≈ 30 °C). 1-Chloropentane adds a C–Cl dipole and more mass (bp ≈ 108 °C). Pentan-1-ol **hydrogen-bonds** (bp ≈ 138 °C), so it comes out **last**.","how":{"ask":"Rank the three by intermolecular forces, which sets their boiling points and so their GC order.","know":"• GC elutes in order of increasing boiling point.\n• Alkene: London only → most volatile.\n• Alkyl halide: dipole–dipole plus London → middle.\n• Alcohol: hydrogen bonding → least volatile, last.","steps":[{"text":"All three have five carbons, so the functional group decides.","hl":"pent-1-ene, 1-chloropentane and pentan-1-ol","calc":["pent-1-ene: London → bp ≈ 30 °C","1-chloropentane: dipole → bp ≈ 108 °C","pentan-1-ol: H-bonding → bp ≈ 138 °C"]},{"text":"The alcohol hydrogen-bonds, so it cannot come out first or second.","strike":["Alcohol, then chloride, then alkene","Alkene, then alcohol, then chloride"]},{"text":"The alkene is more volatile than the chloride, so it comes out before it.","strike":["Chloride, then alkene, then alcohol"]},{"text":"Answer: alkene, then chloride, then alcohol."}],"trap":"Ordering by molar mass alone: the alcohol is lighter than the chloride but comes out after it, because it hydrogen-bonds."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"nonpolar gas chromatography column","note":"order by boiling point"},{"t":"reach the detector","note":"elution order"}]},{"text":"**Name each force.** C=C: London only. C–Cl: a dipole. O–H: hydrogen bonding."},{"text":"**Weakest forces leave first.**","calc":["alkene < alkyl halide < alcohol"]},{"text":"**Also:** in GC, compounds come off in order of increasing boiling point."},{"text":"**Also:** with similar sizes, an alkane boils lowest and an alcohol highest, because hydrogen bonding is the strongest force."},{"text":"**Also:** an O–H or N–H group raises the boiling point far more than added mass does, because of hydrogen bonding."},{"text":"**Rule to reuse:** in GC, an alkene beats an alkyl halide of the same chain, and an alcohol, which hydrogen-bonds, comes out last."}]},
  {"id":"cpt-pe1-09b","s":"Stereochemistry","disc":"organic_chem","aamc":"5B","skill":"SIRS 2","from":["pe1-cp:9#1","pe1-cp:9#2","pe1-cp:9#3"],"q":"(R)-2-Chlorobutane reacts by SN2 with sodium methanethiolate, CH₃SNa. What configuration does the product have?","choices":["(S) only","(R) only","Racemic mixture","Meso compound"],"ans":0,"exp":"SN2 gives **inversion**. The –SCH₃ group (first atom S, 16) now ranks **first**, just as Cl did, and the order of the others (ethyl > methyl > H) is unchanged. Inverting the 3D arrangement with the same priority order flips the label: **R → S**.","how":{"ask":"Apply inversion, then check whether the priorities changed.","know":"• **SN2 → inversion** of the 3D arrangement; no carbocation, so no racemization.\n• **CIP priority** by atomic number of the first atom: S (16) and Cl (17) both outrank C (6) and H (1).\n• If the new group has the same rank as the old one, inversion switches R ↔ S.","steps":[{"text":"The reaction is SN2, so the configuration inverts.","hl":"reacts by SN2","fig":"cpt-sn2-backside"},{"text":"Priorities before and after.","calc":["before: Cl > ethyl > methyl > H","after: **SCH₃** > ethyl > methyl > H"]},{"text":"Same order, inverted geometry, so the label changes; SN2 does not racemize, and the product has one stereocenter.","strike":["(R) only","Racemic mixture","Meso compound"]},{"text":"Answer: (S) only."}],"trap":"Keeping the label R: inversion with unchanged priorities always switches the descriptor."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"(R)-2-Chlorobutane","note":"starting label"},{"t":"SN2","note":"inversion"},{"t":"CH₃SNa","note":"S nucleophile"}]},{"text":"**Flip the umbrella.** The nucleophile enters opposite Cl; the other three groups turn inside out."},{"text":"**Re-rank.** S still outranks every carbon, just as Cl did.","calc":["rank order unchanged → R becomes S"]},{"text":"**Also:** CIP priority is set by the first atom's atomic number; go farther out only to break a tie."},{"text":"**Also:** after a substitution, the product keeps the substrate's carbon chain and the new group's position; only the group's name changes."},{"text":"**Rule to reuse:** SN2 inverts the center; if the entering group takes the leaving group's priority rank, R and S swap."}]},
  {"id":"cpt-pe1-10a","s":"Reaction Mechanisms","disc":"organic_chem","aamc":"5D","skill":"SIRS 3","from":["pe1-cp:10#1","pe1-cp:10#2","pe1-cp:10#3"],"q":"In the acid-catalyzed esterification of acetic acid with ethanol, the oxygen joining the acyl carbon to the ethyl group comes from:","choices":["the ethanol","the acetic acid","the acid catalyst","the water"],"ans":0,"exp":"In Fischer esterification the **alcohol's oxygen is the nucleophile**: it attacks the protonated carbonyl carbon. Later an –OH from the **acid** leaves as water. So the bridging –O– of ethyl acetate is the **ethanol** oxygen.","how":{"ask":"Identify the nucleophile, whose oxygen is kept in the product.","know":"• **Fischer esterification**: RCOOH + R′OH ⇌ RCOOR′ + H₂O (acid catalyst).\n• The **alcohol O attacks** the carbonyl carbon; **water leaves from the acid** side.\n• So the ester's C–O–R′ oxygen comes from the alcohol.","steps":[{"text":"The bridging oxygen links the acyl carbon to the ethyl group.","hl":"the oxygen joining the acyl carbon to the ethyl group"},{"text":"The acid loses one of its oxygens as water; the catalyst only adds and removes H⁺.","strike":["the acetic acid","the acid catalyst","the water"]},{"text":"Answer: the ethanol."}],"trap":"Assuming the acid keeps both oxygens; one of them leaves in the water."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"acid-catalyzed esterification","note":"Fischer"},{"t":"ethanol","note":"the nucleophile"}]},{"text":"**Activate.** H⁺ protonates the acid's C=O, making the carbon more electrophilic."},{"text":"**Attack and leave.**","calc":["EtO–H attacks C → tetrahedral intermediate","acid's –OH → –OH₂⁺ → leaves as H₂O"]},{"text":"**Also:** in Fischer esterification the ester's bridging oxygen comes from the alcohol, its C=O oxygen from the acid, and the water from the acid."},{"text":"**Also:** an H on O or N is a useless label: it exchanges in acid, so it cannot show which bond broke."},{"text":"**Rule to reuse:** in Fischer esterification the alcohol keeps its oxygen as the ester's –O–, and the acid loses an oxygen as water."}]},
  {"id":"cpt-pe1-11a","s":"Light & Optics","disc":"physics","aamc":"4D","skill":"SIRS 1","from":["pe1-cp:11#1","pe1-cp:11#2","pe1-cp:11#3","pe1-cp:45#1","pe1-cp:45#2"],"q":"A camera lens forms a sharp image of a flower 5.0 cm behind the lens when the flower is 20 cm in front. What is the focal length in metres?","choices":["0.040 m","4.0 m","0.067 m","25 m"],"ans":0,"exp":"Convert first: o = 0.20 m and i = 0.050 m. The **thin-lens equation** adds the reciprocals: 1/f = 5 m⁻¹ + 20 m⁻¹ = 25 m⁻¹, so **f = 0.040 m** (4.0 cm).","how":{"ask":"Use the thin-lens equation with both distances converted to metres, then invert to get f.","know":"• **Thin-lens equation: 1/f = 1/o + 1/i** (o = object distance, i = image distance, f = focal length).\n• Work in **metres**: 1 cm = 0.01 m.\n• The equation gives 1/f; flip the result to get f.","steps":[{"text":"Pick out the two distances and convert them to metres.","hl":"5.0 cm behind the lens","calc":["i = 5.0 cm = **0.050 m**","o = 20 cm = **0.20 m**"]},{"text":"Add the reciprocals.","hl":"20 cm in front","calc":["1/f = 1/o + 1/i","1/f = 1/0.20 m + 1/0.050 m","1/f = 5 m⁻¹ + 20 m⁻¹ = **25 m⁻¹**"]},{"text":"Invert to get the focal length.","calc":["f = 1 ÷ 25 m⁻¹ = **0.040 m**"]},{"text":"25 m forgets to invert 1/f. 0.067 m subtracts the reciprocals (20 − 5 = 15 m⁻¹). 4.0 m does the arithmetic in centimetres (f = 4.0 cm) and then labels it metres.","strike":["25 m","0.067 m","4.0 m"]},{"text":"Answer: 0.040 m."}],"trap":"Doing the sum in centimetres gives f = 4.0 cm; that is right in cm, but 4.0 m is a hundred times too large. Convert to metres before you start."},"teach":[{"text":"First, **find every number** and what it measures.","marks":[{"t":"5.0 cm behind the lens","note":"image distance i"},{"t":"20 cm in front","note":"object distance o"},{"t":"in metres","note":"unit of the answer"}]},{"text":"**The thin-lens equation** links the three distances, each measured from the lens.","calc":["1/f = 1/o + 1/i"]},{"text":"**Convert to metres first,** so 1/f comes out in m⁻¹.","calc":["o = 0.20 m → 1/o = 5 m⁻¹","i = 0.050 m → 1/i = 20 m⁻¹"]},{"text":"**Add, then flip.**","calc":["1/f = 25 m⁻¹","f = 0.040 m"]},{"text":"**Also:** power in diopters = 1 ÷ (focal length in metres); converging lenses are +, diverging lenses are −."},{"text":"**Also:** in any eye problem, the image distance is the lens-to-retina distance; the object distance is lens-to-object."},{"text":"**Also:** solve 1/f = 1/o + 1/i for i, then m = −i/o: |m| scales the height and a negative m means inverted."},{"text":"**Also:** for an object beyond 2f, find i from 1/f = 1/o + 1/i and use m = −i/o: the real image is inverted and smaller, shrinking as the object moves away."},{"text":"**Rule to reuse:** convert o and i to metres, add their reciprocals to get 1/f, and remember to invert at the end if the question asks for f."}]},
  {"id":"cpt-pe1-12a","s":"Enzymes & Kinetics","disc":"biochemistry","aamc":"5E","skill":"SIRS 1","from":["pe1-cp:12#1","pe1-cp:12#3"],"q":"A protease binds the tetrahedral intermediate of peptide hydrolysis much more tightly than it binds the intact peptide. How does this binding speed the reaction?","choices":["Lowers activation energy","Makes the reaction exergonic","Shifts equilibrium to products","Raises the temperature"],"ans":0,"exp":"The tetrahedral intermediate resembles the **transition state**. Binding it tightly **stabilizes the transition state**, so the top of the energy hill drops and the **activation energy (Ea)** falls. Reactant and product energies are untouched, so ΔG and the equilibrium stay the same, and an enzyme does not heat the solution.","how":{"ask":"Decide which part of the energy diagram the enzyme changes when it grips the transition-state-like species.","know":"• **Ea = transition-state energy − reactant energy**; a lower Ea means a faster reaction.\n• An enzyme binds the **transition state** more tightly than the substrate, lowering the peak of the curve.\n• **ΔG = products − reactants**: the enzyme does not move either end, so ΔG and K are unchanged.","steps":[{"text":"The enzyme grips the species that looks like the transition state, not the starting peptide.","hl":"binds the tetrahedral intermediate of peptide hydrolysis much more tightly than it binds the intact peptide"},{"text":"Stabilizing the transition state lowers the peak; read both barriers from the curves.","chart":{"type":"line","caption":"Peptide hydrolysis with and without the protease","x":{"label":"Reaction progress","min":0,"max":10,"step":2},"y":{"label":"Free energy (kJ/mol)","min":-40,"max":100,"step":20},"series":[{"name":"No enzyme","marker":"circle","line":"smooth","points":[[0,0],[1,0],[3,40],[5,90],[7,30],[9,-30],[10,-30]]},{"name":"With protease","marker":"square-open","line":"smooth","points":[[0,0],[1,0],[3,20],[5,50],[7,10],[9,-30],[10,-30]]}]},"calc":["Ea without enzyme = 90 − 0 = **90 kJ/mol**","Ea with protease = 50 − 0 = **50 kJ/mol**","ΔG = −30 − 0 = **−30 kJ/mol** on both curves"]},{"text":"Both curves start and end at the same heights, so ΔG and the position of equilibrium are unchanged.","strike":["Makes the reaction exergonic","Shifts equilibrium to products"]},{"text":"An enzyme works at the temperature of its surroundings; it does not heat them.","strike":["Raises the temperature"]},{"text":"Answer: it lowers the activation energy."}],"trap":"Thinking a faster reaction must also be a more favorable one: speed depends on Ea, favorability on ΔG, and an enzyme changes only Ea."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"tetrahedral intermediate","note":"looks like the transition state"},{"t":"much more tightly","note":"preferential binding"},{"t":"speed the reaction","note":"a rate question"}]},{"text":"**Read the energy diagram.** The left plateau is the reactants, the right plateau the products, the peak the transition state. The enzyme's curve has a lower peak but the same ends.","chart":{"type":"line","caption":"Same reaction, two paths","x":{"label":"Reaction progress","min":0,"max":10,"step":2},"y":{"label":"Free energy (kJ/mol)","min":-40,"max":100,"step":20},"series":[{"name":"No enzyme","marker":"circle","line":"smooth","points":[[0,0],[1,0],[3,40],[5,90],[7,30],[9,-30],[10,-30]]},{"name":"With protease","marker":"square-open","line":"smooth","points":[[0,0],[1,0],[3,20],[5,50],[7,10],[9,-30],[10,-30]]}]}},{"text":"**Measure the hill.** Ea is peak minus start.","calc":["no enzyme: 90 − 0 = 90 kJ/mol","with protease: 50 − 0 = 50 kJ/mol","barrier is 40 kJ/mol lower → faster"]},{"text":"**Why tight binding of the transition state works:** the binding energy is released at the peak, which pulls the peak down."},{"text":"**Also:** catalysis needs the transition state stabilized more than the substrate; extra substrate binding alone raises the barrier."},{"text":"**Rule to reuse:** an enzyme speeds a reaction by stabilizing the transition state, which lowers Ea; it never changes the start or end energies."}]},
  {"id":"cpt-pe1-12b","s":"Enzymes & Kinetics","disc":"biochemistry","aamc":"5E","skill":"SIRS 1","from":["pe1-cp:12#2","pe1-cp:50#1"],"q":"An uncatalyzed isomerization has equilibrium constant K at 30 °C. A catalyst is added and the temperature is held constant. Which property of the reaction changes?","choices":["Equilibrium constant","Standard free energy","Time to equilibrium","Equilibrium yield"],"ans":2,"exp":"A catalyst lowers the activation energy of the forward **and** reverse reactions by the same amount, so equilibrium is reached **sooner**. It does not change the energies of reactants or products, so **ΔG°**, **K** (still 6) and the amount of product at equilibrium all stay the same.","how":{"ask":"Separate the properties set by the start and end energies from the one set by the height of the barrier.","know":"• **ΔG° = −RT ln K**: both depend only on reactant and product energies.\n• A catalyst lowers Ea for **both directions** equally, so forward and reverse rates rise by the same factor.\n• Same K → same equilibrium mixture; only the **speed of getting there** changes.","steps":[{"text":"The temperature is fixed, so K can change only if ΔG° changes.","hl":"the temperature is held constant"},{"text":"Compare the two paths: the ends sit at the same heights; only the peak is lower.","chart":{"type":"line","caption":"Isomerization with and without the catalyst","x":{"label":"Reaction progress","min":0,"max":10,"step":2},"y":{"label":"Free energy (kJ/mol)","min":-40,"max":80,"step":20},"series":[{"name":"Uncatalyzed","marker":"circle","line":"smooth","points":[[0,0],[1,0],[3,35],[5,70],[7,20],[9,-20],[10,-20]]},{"name":"Catalyzed","marker":"square-open","line":"smooth","points":[[0,0],[1,0],[3,15],[5,40],[7,0],[9,-20],[10,-20]]}]},"calc":["ΔG° = −20 − 0 = **−20 kJ/mol** on both curves","Ea forward: 70 → 40 kJ/mol","Ea reverse: 70 − (−20) = 90 → 40 − (−20) = 60 kJ/mol","both barriers drop by **30 kJ/mol**"]},{"text":"Same ΔG° means the same K and the same mixture at equilibrium.","strike":["Equilibrium constant","Standard free energy","Equilibrium yield"]},{"text":"Answer: the time to equilibrium, which becomes shorter."}],"trap":"Thinking a catalyst pushes the reaction toward products: it speeds the reverse reaction just as much, so the final mixture is the same."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"equilibrium constant K","note":"set by ΔG°"},{"t":"A catalyst is added","note":"lowers Ea"},{"t":"held constant","note":"no temperature effect"}]},{"text":"**Two different questions.** \"How far?\" is answered by ΔG° and K. \"How fast?\" is answered by Ea."},{"text":"**Link ΔG° and K.** At a fixed temperature they move together, and both depend only on the ends of the diagram.","calc":["ΔG° = −RT ln K","same ends → same ΔG° → same K"]},{"text":"**Both directions speed up.** The catalyst lowers the forward and reverse barriers equally, so the ratio of the forward and reverse rate constants (k_f/k_r = K) is unchanged."},{"text":"**Also:** an inseparable homogeneous catalyst contaminates the product; a catalyst never shifts the equilibrium."},{"text":"**Rule to reuse:** a catalyst changes only how fast equilibrium is reached, never ΔG°, K or the equilibrium mixture."}]},
  {"id":"cpt-pe1-13a","s":"Acids & Bases","disc":"gen_chem","aamc":"5A","skill":"SIRS 2","from":["pe1-cp:13#1","pe1-cp:13#2","pe1-cp:13#3","pe1-cp:13#4"],"q":"A 0.20 M solution of formic acid is prepared. Adding which substance would lower the percent ionization of the formic acid?","choices":["Nitric acid","Pure water","Sodium hydroxide","Sodium bicarbonate"],"ans":0,"exp":"HCOOH ⇌ H⁺ + HCOO⁻. Nitric acid is a **strong acid**, so it floods the solution with **H⁺, an ion already in the equilibrium**. By **Le Châtelier** the equilibrium shifts **left** and a smaller fraction of formic acid ionizes (the **common-ion effect**). Water dilutes the acid, and the two bases remove H⁺; all three raise ionization.","how":{"ask":"For each added substance, decide whether the formic acid equilibrium shifts left (less ionized) or right (more ionized).","know":"• **Percent ionization** = [A⁻] at equilibrium ÷ starting [HA] × 100.\n• **Le Châtelier**: adding a product pushes the equilibrium toward reactants; removing a product pulls it toward products.\n• **Common-ion effect**: a strong acid adds H⁺, a product of HA ⇌ H⁺ + A⁻, so HA ionizes less.","steps":[{"text":"Write the equilibrium for the weak acid in the stem.","hl":"0.20 M solution of formic acid","calc":["HCOOH ⇌ H⁺ + HCOO⁻   (Ka ≈ 1.8 × 10⁻⁴)","alone: x = √(Ka·C) = √(1.8 × 10⁻⁴ × 0.20) = √(3.6 × 10⁻⁵) = 6.0 × 10⁻³ M","% = 6.0 × 10⁻³ ÷ 0.20 × 100 = **3.0%**"]},{"text":"Nitric acid is a strong acid: it adds H⁺, a product, so the equilibrium shifts left. With 0.050 M HNO₃ present:","calc":["x ≈ Ka·C ÷ [H⁺] = 1.8 × 10⁻⁴ × 0.20 ÷ 0.050","x = 7.2 × 10⁻⁴ M","% = 7.2 × 10⁻⁴ ÷ 0.20 × 100 = **0.36%**  (down from 3.0%)"]},{"text":"Water dilutes the acid, and a diluted weak acid ionizes to a larger fraction.","strike":["Pure water"]},{"text":"Both bases remove H⁺ (OH⁻ + H⁺ → H₂O; HCO₃⁻ + H⁺ → H₂CO₃), so the equilibrium shifts right: more ionization.","strike":["Sodium hydroxide","Sodium bicarbonate"]},{"text":"Answer: nitric acid."}],"trap":"Choosing a base because it \"neutralizes\" the acid: removing H⁺ pulls the equilibrium to the right, so the weak acid ionizes more, not less."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"formic acid","note":"weak acid: HCOOH ⇌ H⁺ + HCOO⁻"},{"t":"lower the percent ionization","note":"shift the equilibrium left"}]},{"text":"**Percent ionization** is the fraction of the acid molecules that have given up their H⁺.","calc":["% ionization = [A⁻] ÷ [HA]₀ × 100"]},{"text":"**Le Châtelier:** add a product and the equilibrium moves back toward the reactant. H⁺ is a product, so an extra source of H⁺ makes less HA ionize.","calc":["add H⁺ → shift left → % ionization down","remove H⁺ → shift right → % ionization up"]},{"text":"**Also:** diluting a weak acid lowers [H⁺] but raises its percent ionization."},{"text":"**Also:** an electron-withdrawing substituent (such as Cl) near the acidic group makes the acid stronger, so it ionizes more."},{"text":"**Also:** a drop of indicator is too small an amount to change an acid's equilibrium or its percent ionization."},{"text":"**Rule to reuse:** adding a strong acid (a common ion, H⁺) lowers a weak acid's percent ionization; adding a base raises it."}]},
  {"id":"cpt-pe1-56a","s":"Electricity & Magnetism","disc":"physics","aamc":"4C","skill":"SIRS 2","from":["pe1-cp:56#1","pe1-cp:14#1"],"q":"A heating element with a resistance of 250 mΩ is connected across a 4.5-V supply. Assuming constant resistance, how much current does it draw?","choices":["18 A","18 mA","56 A","0.056 A"],"ans":0,"exp":"Convert first: **250 mΩ = 0.250 Ω**. Then **Ohm's law, I = V/R** = 4.5 V ÷ 0.250 Ω = **18 A**. A resistance under 1 Ω gives a current larger than the voltage number.","how":{"ask":"Put the resistance in ohms, then divide the voltage by it.","know":"• **Ohm's law: I = V/R** (A = V ÷ Ω).\n• **m (milli) = 10⁻³**: 1 mΩ = 0.001 Ω. Capital **M (mega) = 10⁶**.","steps":[{"text":"Convert milliohms to ohms.","hl":"a resistance of 250 mΩ","calc":["250 mΩ = 250 × 10⁻³ Ω = **0.250 Ω**"]},{"text":"Apply Ohm's law.","hl":"4.5-V supply","calc":["I = V ÷ R","I = 4.5 V ÷ 0.250 Ω","I = **18 A**"],"chart":{"type":"line","caption":"Current from a 4.5-V supply versus resistance","x":{"label":"Resistance (Ω)","min":0,"max":3,"step":0.5},"y":{"label":"Current (A)","min":0,"max":20,"step":5},"series":[{"name":"I = V ÷ R","marker":"circle","line":"smooth","points":[[0.25,18],[0.5,9],[0.75,6],[1,4.5],[1.5,3],[2,2.25],[3,1.5]]}]}},{"text":"18 mA divides by 250 Ω, skipping the milli conversion. 56 A divides 250 by 4.5, which is R ÷ V and unconverted. 0.056 A is R ÷ V in ohms, the ratio upside down.","strike":["18 mA","56 A","0.056 A"]},{"text":"Answer: 18 A."}],"trap":"Treating 250 mΩ as 250 Ω gives 18 mA, a thousand times too small."},"teach":[{"text":"First, **find the givens**.","marks":[{"t":"250 mΩ","note":"resistance R (milliohms)"},{"t":"4.5-V supply","note":"voltage V"},{"t":"how much current","note":"I in amps"}]},{"text":"**Milli means one thousandth.** Convert before dividing.","calc":["250 mΩ = 250 ÷ 1000 Ω = 0.250 Ω"]},{"text":"**Ohm's law:** current = voltage ÷ resistance.","calc":["I = V ÷ R = 4.5 ÷ 0.250 = 18 A"]},{"text":"**Also:** at constant resistance, V = IR makes voltage directly proportional to current."},{"text":"**Rule to reuse:** I = V/R with R in ohms; convert mΩ by dividing by 1000 first, and expect more amps than volts when R is under 1 Ω."}]},
  {"id":"cpt-pe1-15a","s":"Light & Optics","disc":"physics","aamc":"4D","skill":"SIRS 2","from":["pe1-cp:15#1"],"q":"In vacuum, light travels at 300,000 km/s; inside a plastic lens it travels at 200,000 km/s. What is the plastic's index of refraction?","choices":["1.5","0.67","0.50","0.33"],"ans":0,"exp":"**n = c/v** = 300,000 ÷ 200,000 = **1.5**. Light is never faster in a material than in vacuum, so every real index is at least 1; the three values below 1 are impossible.","how":{"ask":"Divide the speed of light in vacuum by its speed in the plastic, then check that n ≥ 1.","know":"• **Index of refraction: n = c/v** (c = speed in vacuum, v = speed in the material).\n• Since v ≤ c, **n ≥ 1 always** (n = 1 only for vacuum).","steps":[{"text":"Pick out the two speeds.","hl":"300,000 km/s","calc":["c = 300,000 km/s","v = 200,000 km/s"]},{"text":"Apply n = c/v; the units cancel.","hl":"200,000 km/s","calc":["n = c ÷ v","n = 300,000 ÷ 200,000","n = **1.5**"]},{"text":"0.67 is v/c, the ratio upside down. 0.50 and 0.33 compare the speed difference with v or c. All are below 1, which would mean light moves faster than in vacuum.","strike":["0.67","0.50","0.33"]},{"text":"Answer: 1.5."}],"trap":"Writing v/c instead of c/v. Any index below 1 is a red flag that the ratio is flipped."},"teach":[{"text":"First, **find the two speeds**.","marks":[{"t":"300,000 km/s","note":"c, in vacuum"},{"t":"200,000 km/s","note":"v, in plastic"},{"t":"index of refraction","note":"n = c/v"}]},{"text":"**The index says how many times slower light is** in the material than in vacuum.","calc":["n = c ÷ v"]},{"text":"**Fast over slow.** The bigger speed goes on top, so n comes out at least 1.","calc":["300,000 ÷ 200,000 = 1.5"]},{"text":"**Rule to reuse:** n = c/v, and n ≥ 1 for every material; a value below 1 means the ratio was flipped."}]},
  {"id":"cpt-pe1-16a","s":"Light & Optics","disc":"physics","aamc":"4D","skill":"SIRS 1","from":["pe1-cp:16#1"],"q":"Two lamps emit the same 590-nm yellow light, but lamp X is three times as intense as lamp Y. What is tripled for lamp X?","choices":["Photon arrival rate","Energy of each photon","Speed of the photons","Degree of polarization"],"ans":0,"exp":"**Intensity = (photons per second × energy per photon) ÷ area.** One wavelength means one photon energy (E = hc/λ), so the only way to triple the intensity is to deliver **three times as many photons each second**. Light speed and polarization do not set intensity.","how":{"ask":"Split intensity into its two factors. Which factor can change while the wavelength stays fixed?","know":"• **Intensity** = power ÷ area = (photons per second) × (energy per photon) ÷ area.\n• **E = hf = hc/λ**: the energy of one photon depends only on its color.\n• Light speed in air is fixed at about c = 3.00 × 10⁸ m/s, whatever the brightness.\n• **Polarization** is the direction the electric field oscillates in; it describes orientation, not amount.","steps":[{"text":"Same wavelength for both lamps, so every photon carries the same energy.","hl":"the same 590-nm yellow light","calc":["E = hc ÷ λ","E = (6.63 × 10⁻³⁴ J·s)(3.00 × 10⁸ m/s) ÷ (590 × 10⁻⁹ m)","E ≈ **3.4 × 10⁻¹⁹ J** per photon, for both lamps"],"strike":["Energy of each photon"]},{"text":"Light from both lamps travels at c, and polarization only describes the direction of the field's oscillation, not how much light arrives.","strike":["Speed of the photons","Degree of polarization"]},{"text":"Write intensity as a product and triple it: the only factor left to change is the photon rate.","hl":"three times as intense","calc":["I = (photons/s × E) ÷ A","3I = (**3** × photons/s) × (same E) ÷ A"],"chart":{"type":"line","caption":"Intensity of 590-nm light versus photon arrival rate","x":{"label":"Photons per second (relative)","min":0,"max":4,"step":1},"y":{"label":"Intensity (relative)","min":0,"max":4,"step":1},"series":[{"name":"Intensity","marker":"circle","line":"straight","points":[[0,0],[1,1],[2,2],[3,3],[4,4]]}]}},{"text":"Answer: photon arrival rate."}],"trap":"Picking 'Energy of each photon' because intensity is an energy flow. If each photon carried more energy, the wavelength, and so the color, would have changed."},"teach":[{"text":"First, **find what is the same and what differs**.","marks":[{"t":"the same 590-nm yellow light","note":"same color: same λ"},{"t":"three times as intense","note":"brighter by 3×"},{"t":"What is tripled","note":"find the factor that grew"}]},{"text":"**Light comes in photons.** Each photon's energy is set by its color alone.","calc":["E = hf = hc/λ","same λ → same E"]},{"text":"**Intensity counts energy arriving per second on each square metre.** It is photons per second times energy per photon.","calc":["I = (photons/s × E) ÷ A"]},{"text":"**See it:** at one color, intensity rises in a straight line with the photon rate.","chart":{"type":"line","caption":"Fixed color: intensity is proportional to photons per second","x":{"label":"Photons per second (relative)","min":0,"max":4,"step":1},"y":{"label":"Intensity (relative)","min":0,"max":4,"step":1},"series":[{"name":"Intensity","marker":"circle","line":"straight","points":[[0,0],[1,1],[2,2],[3,3],[4,4]]}]}},{"text":"**Rule to reuse:** for light of one color, intensity is proportional to the number of photons per second; speed, wavelength and polarization do not set it."}]},
  {"id":"cpt-pe1-17a","s":"Light & Optics","disc":"physics","aamc":"4D","skill":"SIRS 2","from":["pe1-cp:17#1"],"q":"A green LED emits light at a frequency of 580 THz. Using Planck's constant in eV·s, how much energy does each emitted photon carry?","choices":["2.4 eV","0.0024 eV","0.24 eV","2400 eV"],"ans":0,"exp":"**E = hf** with **tera = 10¹²**: f = 5.8 × 10¹⁴ Hz, and E = (4.14 × 10⁻¹⁵ eV·s)(5.8 × 10¹⁴ s⁻¹) = 24 × 10⁻¹ eV = **2.4 eV**, a typical visible-light photon energy.","how":{"ask":"Convert THz to Hz, multiply by Planck's constant in eV·s, and combine the powers of ten.","know":"• **E = hf**: E = photon energy, h = Planck's constant, f = frequency (Hz = s⁻¹).\n• **h = 6.63 × 10⁻³⁴ J·s = 4.14 × 10⁻¹⁵ eV·s** (1 eV = 1.60 × 10⁻¹⁹ J).\n• Prefixes: giga 10⁹, **tera 10¹²**, peta 10¹⁵.\n• Visible photons carry roughly 1.7–3.1 eV.","steps":[{"text":"The frequency is given, so use E = hf.","hl":"a frequency of 580 THz","calc":["E = h × f"]},{"text":"Convert the prefix: tera = 10¹².","calc":["580 THz = 580 × 10¹² Hz","= **5.8 × 10¹⁴ Hz**"]},{"text":"Multiply the numbers and add the exponents separately.","calc":["E = (4.14 × 10⁻¹⁵ eV·s)(5.8 × 10¹⁴ s⁻¹)","4.14 × 5.8 = 24.0","10⁻¹⁵ × 10¹⁴ = 10⁻¹","E = 24.0 × 10⁻¹ eV = **2.4 eV**"]},{"text":"Check in joules: (6.63 × 10⁻³⁴)(5.8 × 10¹⁴) = 3.8 × 10⁻¹⁹ J, and 3.8 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ ≈ 2.4 eV.","calc":["3.8 × 10⁻¹⁹ J ÷ 1.60 × 10⁻¹⁹ J/eV ≈ **2.4 eV**"]},{"text":"0.0024 eV treats tera as giga (10⁹). 2400 eV treats it as peta (10¹⁵). 0.24 eV writes 580 THz as 5.8 × 10¹³ Hz, one power of ten short.","strike":["0.0024 eV","2400 eV","0.24 eV"]},{"text":"Answer: 2.4 eV."}],"trap":"Slipping one prefix step (tera as giga) shifts the answer by a factor of 1000. A visible photon always carries a few eV, so 0.0024 eV or 2400 eV is a unit slip."},"teach":[{"text":"First, **find the number and its unit**.","marks":[{"t":"580 THz","note":"frequency f"},{"t":"eV·s","note":"use h in eV·s"},{"t":"each emitted photon","note":"energy of a single photon"}]},{"text":"**One photon's energy is Planck's constant times frequency.**","calc":["E = hf","h = 4.14 × 10⁻¹⁵ eV·s"]},{"text":"**Tera means 10¹².** Write the frequency in scientific notation before multiplying.","calc":["580 THz = 5.8 × 10¹⁴ Hz"]},{"text":"**Numbers and powers of ten separately.** Multiply 4.14 × 5.8, then add −15 and +14.","calc":["4.14 × 5.8 = 24.0","10⁻¹⁵ × 10¹⁴ = 10⁻¹","E = 2.4 eV"]},{"text":"**Rule to reuse:** E = hf with f in hertz (THz × 10¹²); multiply the leading numbers and add the exponents, then check that a visible photon comes out near 2–3 eV."}]},
  {"id":"cpt-pe1-18a","s":"Fluids","disc":"physics","aamc":"4B","skill":"SIRS 1","from":["pe1-cp:18#1"],"q":"A fluid's gauge pressure at depth h is P = ρgh, and its density is ρ = m/V. Which expression gives the depth h?","choices":["PV/(mg)","mg/(PV)","Pm/(Vg)","P/(mVg)"],"ans":0,"exp":"Substitute the density definition: P = (m/V)gh. Multiply both sides by V to clear the fraction: PV = mgh. Divide by mg: **h = PV/(mg)**.","how":{"ask":"Put the density definition into the pressure equation, clear the fraction, then isolate h.","know":"• **Substitution**: replace ρ with m/V.\n• **Clear a fraction** by multiplying both sides by its denominator (here V).\n• Then divide both sides by everything still multiplying h.","steps":[{"text":"Substitute ρ = m/V into P = ρgh.","hl":"ρ = m/V","calc":["P = (m/V) g h"]},{"text":"Multiply through by the denominator V.","hl":"P = ρgh","calc":["P × V = m g h","PV = mgh"]},{"text":"Divide both sides by mg.","calc":["h = **PV/(mg)**"]},{"text":"mg/(PV) is the result flipped. Pm/(Vg) comes from substituting ρ = V/m, the density definition upside down. P/(mVg) treats density as m × V instead of m ÷ V.","strike":["mg/(PV)","Pm/(Vg)","P/(mVg)"]},{"text":"Answer: PV/(mg)."}],"trap":"Putting V in the denominator: since ρ = m/V, the V sits under m, and moving it across the equals sign puts it on top with P."},"teach":[{"text":"First, **find the two definitions** and the unknown.","marks":[{"t":"P = ρgh","note":"pressure equation"},{"t":"ρ = m/V","note":"density definition"},{"t":"depth h","note":"isolate this"}]},{"text":"**Substitute.** Wherever ρ appears, write m/V.","calc":["P = (m/V)gh"]},{"text":"**Clear the fraction.** Multiply every term by V.","calc":["PV = mgh"]},{"text":"**Isolate h.** Divide by what multiplies it, then check units: (Pa·m³)/(kg·m/s²) = m ✓.","calc":["h = PV/(mg)"]},{"text":"**Rule to reuse:** substitute one definition into the other, multiply through by the fraction's denominator, then divide to isolate the variable."}]},
  {"id":"cpt-pe1-19d","s":"Fluids","disc":"gen_chem","aamc":"4B","skill":"SIRS 1","from":["pe1-cp:19#4","pe1-cp:19#1","pe1-cp:19#2","pe1-cp:19#3"],"q":"A patient's systolic pressure is 95 mmHg. Expressed as a percentage of atmospheric pressure, about how large is this value?","choices":["12.5%","8.0%","94%","0.13%"],"ans":0,"exp":"Write both pressures in **the same unit**, mmHg: 95 ÷ 760 = 0.125, and 0.125 × 100 = **12.5%**. 8.0 inverts the ratio, 94% divides mmHg by kPa, and 0.13% forgets to multiply by 100.","how":{"ask":"Divide the patient's pressure by atmospheric pressure in matching units, then convert to a percentage.","know":"• **1 atm = 760 mmHg**.\n• **% = value ÷ 760 mmHg × 100** when the value is in mmHg.\n• Never divide mmHg by kPa.","steps":[{"text":"Note the value and its unit.","hl":"95 mmHg","calc":["value = 95 mmHg","1 atm = 760 mmHg"]},{"text":"Divide, then multiply by 100.","calc":["95 ÷ 760 = 0.125","0.125 × 100 = **12.5%**"]},{"text":"Eliminate the slips: 8.0 = 760 ÷ 95 (inverted); 94% ≈ 95 ÷ 101 (mmHg over kPa); 0.13% ≈ 0.125 written as a percent without the × 100.","strike":["8.0%","94%","0.13%"]},{"text":"Answer: 12.5%."}],"trap":"Dividing by 101: that is atmospheric pressure in kPa, and dividing mmHg by kPa gives a meaningless number near 94%."},"teach":[{"text":"First, **find the number and what to compare it with**.","marks":[{"t":"95 mmHg","note":"the value"},{"t":"atmospheric pressure","note":"760 mmHg"}]},{"text":"**Same units first.** The value is in mmHg, so use 1 atm = 760 mmHg."},{"text":"**Percentage = fraction × 100.**","calc":["% = value ÷ 760 × 100"]},{"text":"**Also:** a typical healthy adult's blood pressure is about 120/80 mmHg (systolic/diastolic)."},{"text":"**Also:** pulse pressure = systolic − diastolic."},{"text":"**Also:** 1 atm = 760 mmHg; multiply atm by 760 to get mmHg."},{"text":"**Rule to reuse:** percent of 1 atm = (pressure in mmHg ÷ 760) × 100."}]},
  {"id":"cpt-pe1-20b","s":"Atomic & Nuclear Physics","disc":"physics","aamc":"4E","skill":"SIRS 2","from":["pe1-cp:20#2","pe1-cp:20#1","pe1-cp:20#3"],"q":"Strontium-90 has a half-life of 29 years. How much of a 40 mg sample of it remains after 87 years?","choices":["5 mg","10 mg","20 mg","35 mg"],"ans":0,"exp":"n = 87 ÷ 29 = **3** half-lives. **Remaining = starting amount × (½)ⁿ** = 40 mg × ⅛ = **5 mg**. 35 mg is the amount that decayed, not the amount left.","how":{"ask":"Count the half-lives, then halve the starting amount that many times.","know":"• n = t ÷ t½.\n• **Remaining = N₀ × (½)ⁿ**.\n• Decayed = N₀ − remaining.","steps":[{"text":"Note the starting mass, the half-life and the time.","hl":"40 mg","calc":["N₀ = 40 mg","t½ = 29 y, t = 87 y"]},{"text":"Count half-lives.","hl":"87 years","calc":["n = 87 ÷ 29 = **3**"]},{"text":"Halve three times.","calc":["(½)³ = ⅛","40 mg × ⅛ = **5 mg**","40 → 20 → 10 → 5 mg"],"chart":{"type":"line","caption":"Strontium-90 remaining in a 40 mg sample","x":{"label":"Time (years)","min":0,"max":87,"step":29},"y":{"label":"Mass remaining (mg)","min":0,"max":40,"step":10},"series":[{"name":"Sr-90 left","marker":"circle","line":"smooth","points":[[0,40],[29,20],[58,10],[87,5]]}]}},{"text":"20 mg is after one half-life and 10 mg after two; 35 mg (40 − 5) is what decayed.","strike":["20 mg","10 mg","35 mg"]},{"text":"Answer: 5 mg."}],"trap":"Answering 35 mg: that is the decayed mass. The question asks what remains."},"teach":[{"text":"First, **find every number**.","marks":[{"t":"half-life of 29 years","note":"t½"},{"t":"40 mg","note":"starting amount"},{"t":"87 years","note":"elapsed time"}]},{"text":"**Count half-lives:** n = t ÷ t½.","calc":["n = 87 ÷ 29 = 3"]},{"text":"**Halve n times**, which is the same as multiplying by (½)ⁿ.","chart":{"type":"line","caption":"Each half-life halves the mass","x":{"label":"Time (years)","min":0,"max":87,"step":29},"y":{"label":"Mass remaining (mg)","min":0,"max":40,"step":10},"series":[{"name":"Sr-90 left","marker":"circle","line":"smooth","points":[[0,40],[29,20],[58,10],[87,5]]}]}},{"text":"**Also:** number of half-lives n = elapsed time ÷ half-life."},{"text":"**Also:** fraction decayed = 1 − (½)ⁿ, where n = time ÷ half-life."},{"text":"**Rule to reuse:** amount remaining = starting amount × (½)ⁿ, with n = time ÷ half-life."}]},
  {"id":"cpt-pe1-21b","s":"Reading Data","disc":"physics","aamc":"4A","skill":"SIRS 4","from":["pe1-cp:21#2","pe1-cp:21#1","pe1-cp:21#3"],"q":"A pump moves 24 L in 4.0 min. Its power curve passes through 4 W at 0 L/min, 10 W at 2 L/min, 16 W at 4 L/min and 22 W at 6 L/min. What power does the pump draw?","choices":["22 W","16 W","4 W","88 W"],"ans":0,"exp":"First find the operating flow: 24 L ÷ 4.0 min = **6 L/min**. Then read the curve at that flow: **22 W**. Reading at 4 confuses the time with the flow.","how":{"ask":"Work out the flow rate in L/min, then read the power at that flow on the curve.","know":"• **Flow rate = volume ÷ time**, in the axis units (L/min).\n• To read a graph: find the x value, go up to the curve, read across to y.","steps":[{"text":"Compute the flow rate in the graph's units.","hl":"24 L in 4.0 min","calc":["Q = 24 L ÷ 4.0 min = **6 L/min**"]},{"text":"Read the curve at 6 L/min.","hl":"22 W at 6 L/min","calc":["P(6 L/min) = **22 W**"],"chart":{"type":"line","caption":"Pump power versus flow rate","x":{"label":"Flow rate (L/min)","min":0,"max":8,"step":2},"y":{"label":"Power (W)","min":0,"max":30,"step":5},"series":[{"name":"Power","marker":"circle","line":"straight","points":[[0,4],[2,10],[4,16],[6,22],[8,28]]}]}},{"text":"16 W is read at x = 4, the number of minutes. 4 W is the curve at almost zero flow, what you get by using the per-second rate (0.1 L/s) on a per-minute axis. 88 W multiplies the power by the time, which gives work, not power.","strike":["16 W","4 W","88 W"]},{"text":"Answer: 22 W."}],"trap":"Reading the graph at a number from the stem (4.0 min) instead of at the computed flow rate."},"teach":[{"text":"First, **find every number** and what it is.","marks":[{"t":"24 L","note":"volume"},{"t":"4.0 min","note":"time"},{"t":"power curve","note":"P read from flow"}]},{"text":"**Get the x value.** The curve's x-axis is flow in L/min.","calc":["24 L ÷ 4.0 min = 6 L/min"]},{"text":"**Go up to the curve, then across.** At 6 L/min the line sits at 22 W.","chart":{"type":"line","caption":"Read power at the operating flow","x":{"label":"Flow rate (L/min)","min":0,"max":8,"step":2},"y":{"label":"Power (W)","min":0,"max":30,"step":5},"series":[{"name":"Power","marker":"circle","line":"straight","points":[[0,4],[2,10],[4,16],[6,22],[8,28]]}]}},{"text":"**Also:** compute a rate in exactly the units of the graph's axis before reading the graph."},{"text":"**Also:** work = power × time, with power in watts and time in seconds, giving joules."},{"text":"**Rule to reuse:** compute the x value in the axis's units, then read the curve at that x; never read at a raw number from the question."}]},
  {"id":"cpt-pe1-22a","s":"Protein Structure","disc":"biochemistry","aamc":"5D","skill":"SIRS 2","from":["pe1-cp:22#1","pe1-cp:22#2","pe1-cp:22#3"],"q":"A purified enzyme left in air slowly forms a link between two of its cysteine side chains. What kind of interaction is this link?","choices":["Covalent bond","Hydrogen bond","Salt bridge","London dispersion"],"ans":0,"exp":"O₂ from the air **oxidizes** the side chains: each cysteine **thiol (–SH)** loses its H and the two sulfurs bond, giving a **disulfide (–S–S–)**. Electrons are shared between the sulfurs, so it is a **covalent bond**, far stronger than hydrogen bonds, salt bridges or dispersion forces.","how":{"ask":"Name the link that forms when cysteine side chains are oxidized, then classify it.","know":"• Cysteine side chain: –CH₂–**SH** (a thiol).\n• **Oxidation**: 2 R–SH → R–S–S–R + 2 H⁺ + 2 e⁻ (a **disulfide**).\n• The S–S bond is a shared electron pair: **covalent**.\n• Hydrogen bonds, salt bridges and dispersion forces are noncovalent and do not need oxidation.","steps":[{"text":"Air is the oxidant and cysteine is the residue.","hl":"left in air slowly forms a link between two of its cysteine side chains"},{"text":"Write the reaction.","calc":["2 Cys–SH + ½ O₂ → Cys–S–S–Cys + H₂O","S–S = shared electron pair → **covalent**"]},{"text":"These are noncovalent attractions, and none needs oxidation to form.","strike":["Hydrogen bond","Salt bridge","London dispersion"]},{"text":"Answer: a covalent bond (a disulfide)."}],"trap":"Calling the disulfide a weak side-chain interaction like the others in tertiary structure: it is the one covalent cross-link among them."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"left in air","note":"O₂ oxidizes"},{"t":"cysteine side chains","note":"thiols, –SH"}]},{"text":"**Cysteine carries a thiol.** Its side chain ends in S–H.","fig":"cysteine"},{"text":"**Oxidation joins two thiols.** Both H's leave and the sulfurs bond to each other.","calc":["R–SH + HS–R → R–S–S–R"]},{"text":"**Classify the bond.** The sulfurs share electrons: a covalent bond, unlike the noncovalent forces that also shape proteins."},{"text":"**Also:** a disulfide is always covalent; it is intermolecular when its two cysteines belong to different molecules."},{"text":"**Also:** reducing agents such as β-mercaptoethanol or DTT break disulfides back into two thiols."},{"text":"**Rule to reuse:** oxidizing two cysteine thiols makes a disulfide, a covalent S–S bond."}]},
  {"id":"cpt-pe1-23c","s":"Amino Acids & Proteins","disc":"biochemistry","aamc":"5D","skill":"SIRS 2","from":["pe1-cp:23#3","pe1-cp:23#1","pe1-cp:23#2"],"q":"A designed peptide has a cross-linking region A (Gly–Cys–Gly–Cys) and a cell-binding region B (Lys–Glu–Arg–Asp). Which residue gives cells a charged group to bind?","choices":["Arg in region B","Cys in region A","Gly in region A","Cys in region B"],"ans":0,"exp":"Match each residue to its region first. Region A holds **Gly** (no side chain) and **Cys** (a thiol for disulfide cross-links), so it offers no charge. Region B holds Lys, Glu, Arg and Asp, all **charged** at body pH; **Arg** is one of them. There is no Cys in region B.","how":{"ask":"List the residues in each region, then find a charged one in the region where it actually sits.","know":"• Charged at body pH: Asp −, Glu −, Lys +, Arg +.\n• **Cys** = thiol for **disulfide cross-links**, not a charge.\n• **Gly** = no side chain.\n• A choice must name a residue that is really in the region it names.","steps":[{"text":"Write out the two regions.","hl":"Gly–Cys–Gly–Cys","calc":["region A: Gly, Cys → cross-linking","region B: Lys, Glu, Arg, Asp → all charged"]},{"text":"Region A has no charged side chain: Gly has none, and Cys forms disulfides.","strike":["Cys in region A","Gly in region A"]},{"text":"Cys does not appear in region B, so that pairing is wrong.","hl":"Lys–Glu–Arg–Asp","strike":["Cys in region B"]},{"text":"Answer: Arg in region B."}],"trap":"Choosing cysteine because its sulfur looks reactive: it belongs to the cross-linking region and gives a covalent link between strands, not a charge for cells."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"cross-linking region A","note":"Cys for disulfides"},{"t":"cell-binding region B","note":"charged residues"},{"t":"charged group","note":"Asp, Glu, Lys, Arg"}]},{"text":"**Sort by job.** Cys makes S–S cross-links; Gly is a spacer; charged residues bind cells.","fig":["cysteine","glycine"]},{"text":"**Check the charged ones.**","calc":["Lys +, Arg +","Glu −, Asp −"],"fig":["arginine","glutamate"]},{"text":"**Check the location too.** A right residue in the wrong region is a wrong answer."},{"text":"**Also:** for an electrostatic contact, choose a side chain charged opposite to the partner: Lys or Arg for a − site, Asp or Glu for a + site."},{"text":"**Also:** glycine has no side chain (R = H), so it adds no charge or functional group to a binding site."},{"text":"**Rule to reuse:** match each residue to its labeled region and its job: Cys cross-links, Gly adds nothing, and Asp, Glu, Lys, Arg give charges."}]},
  {"id":"cpt-pe1-24c","s":"Amino Acids & Proteins","disc":"biochemistry","aamc":"5D","skill":"SIRS 2","from":["pe1-cp:24#3","pe1-cp:24#1","pe1-cp:24#2"],"q":"A report states that a regulatory phosphate is attached to a residue whose side chain is a primary alcohol. Which residue carries the phosphate?","choices":["Serine","Threonine","Tyrosine","Cysteine"],"ans":0,"exp":"A **primary alcohol** has its –OH on a carbon bonded to only one other carbon: **–CH₂–OH**. That is serine's side chain. Threonine's –OH is on a carbon with two carbon neighbors (secondary), tyrosine's is on a ring (a phenol), and cysteine has –SH, not –OH.","how":{"ask":"Which side chain matches the description the report gives: an –OH on a carbon with one carbon neighbor?","know":"• **Primary alcohol**: –CH₂–OH (1 C on the carbinol carbon).\n• Ser –CH₂OH (1°); Thr –CH(OH)CH₃ (2°); Tyr ring–OH (phenol); Cys –CH₂SH (thiol).\n• Use the description given, not the residue you expect to see phosphorylated.","steps":[{"text":"The report's clue is the class of alcohol.","hl":"side chain is a primary alcohol"},{"text":"Find the side chain that ends in –CH₂–OH.","fig":["serine-sc","t1-phosphoserine"],"calc":["Ser: –CH₂–OH → C bearing OH has 1 C neighbor → **1°** ✓"]},{"text":"Threonine's OH carbon has two carbon neighbors (secondary), and tyrosine's OH sits on a ring (phenol).","strike":["Threonine","Tyrosine"]},{"text":"Cysteine ends in –CH₂–SH: a thiol, not an alcohol.","strike":["Cysteine"]},{"text":"Answer: serine."}],"trap":"Picking tyrosine or threonine because they are also phosphorylated: the report names a primary alcohol, and only serine fits."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"primary alcohol","note":"–CH₂–OH"},{"t":"regulatory phosphate","note":"on an –OH"}]},{"text":"**Translate the description into a structure.** Primary means the –OH carbon has one carbon neighbor.","calc":["primary: R–CH₂–OH","secondary: R–CH(OH)–R′","phenol: ring–OH"]},{"text":"**Match it to a side chain.** Only serine ends in –CH₂–OH.","fig":"serine-sc"},{"text":"**Also:** serine is a primary alcohol, threonine a secondary alcohol, tyrosine a phenol, and alanine only a methyl group."},{"text":"**Also:** phosphorylation goes on a side-chain –OH, so look for Ser, Thr or Tyr and reject side chains with no hydroxyl."},{"text":"**Rule to reuse:** turn the description into a structure first (primary alcohol → –CH₂OH → serine), then pick the residue that matches it."}]},
  {"id":"cpt-pe1-25c","s":"Amino Acids & Proteins","disc":"biochemistry","aamc":"5D","skill":"SIRS 3","from":["pe1-cp:25#3","pe1-cp:25#1","pe1-cp:25#2"],"q":"A peptide's only ionizable side chains are histidines, with pKa 6.0. At pH 8.0, what is the main form of these side chains?","choices":["Mostly neutral","Mostly positive","Half positive","Mostly negative"],"ans":0,"exp":"pH 8.0 is **two units above** the pKa, so by Henderson–Hasselbalch the neutral (base) form outnumbers the protonated (+1) form **100 : 1**. About 99% of the histidines are neutral. They would be half positive only at pH 6.0 and mostly positive below it; a histidine side chain never turns negative.","how":{"ask":"How far is the pH from the pKa, and which side of it is the pH on?","know":"• **pH = pKa + log([base]/[acid])**.\n• Histidine: acid form = imidazolium (+1); base form = neutral imidazole (0).\n• Each pH unit away from the pKa is a 10-fold change in the ratio.","steps":[{"text":"Pick out the pKa and the pH.","hl":"pKa 6.0"},{"text":"Apply Henderson–Hasselbalch.","calc":["log([base]/[acid]) = pH − pKa","= 8.0 − 6.0 = 2.0","[base]/[acid] = 10² = **100 : 1**","fraction neutral = 100/101 ≈ **99%**"]},{"text":"See it on the titration curve: at pH 8 almost none is protonated.","chart":{"type":"line","caption":"Histidine side chain protonated (pKa 6.0)","x":{"label":"pH","min":3,"max":9,"step":1},"y":{"label":"Protonated, +1 (%)","min":0,"max":100,"step":20},"series":[{"name":"Protonated","marker":"circle","line":"smooth","points":[[3,99.9],[4,99],[5,91],[5.5,76],[6,50],[6.5,24],[7,9],[8,1],[9,0.1]]}]}},{"text":"Half positive happens only at pH = pKa; mostly positive needs pH below 6.0.","strike":["Half positive","Mostly positive"]},{"text":"Losing its proton leaves histidine neutral, not negative.","strike":["Mostly negative"]},{"text":"Answer: mostly neutral."}],"trap":"Thinking of histidine as a 'basic, positive' residue regardless of pH: above its pKa of 6.0 it is mostly uncharged."},"teach":[{"text":"First, **find every number**.","marks":[{"t":"pKa 6.0","note":"histidine side chain"},{"t":"pH 8.0","note":"two units above"}]},{"text":"**Compare pH with pKa.** pH above pKa → mostly deprotonated; below → mostly protonated.","calc":["8.0 − 6.0 = +2"]},{"text":"**Each unit is a factor of 10.** Two units above the pKa → 100 base : 1 acid.","fig":"histidine-sc","calc":["10² = 100 → ≈ 99% neutral"]},{"text":"**Also:** a side chain's charge changes only when the pH moves past its pKa; acids go 0 → −1, bases go +1 → 0 as pH rises."},{"text":"**Also:** charged side chains repel and keep peptides apart; when the pH neutralizes them, the strands can pack together."},{"text":"**Rule to reuse:** compare pH with each side chain's pKa; one unit past it is about 90% converted, two units about 99%."}]},
  {"id":"cpt-pe1-26a","s":"Fluids","disc":"biology","aamc":"4B","skill":"SIRS 1","from":["pe1-cp:26#1"],"q":"In a muscle bed, blood moves at 2.0 cm/s through arterioles with a combined cross-sectional area of 40 cm². The capillaries they feed total 800 cm². What is the capillary blood speed?","choices":["0.10 cm/s","2.0 cm/s","40 cm/s","0.0025 cm/s"],"ans":0,"exp":"**Continuity: Q = A·v is the same at every level.** Q = 40 cm² × 2.0 cm/s = 80 cm³/s, so v = 80 ÷ 800 = **0.10 cm/s**. Blood crawls through capillaries because their **total** area is twenty times larger, not because each one is thin.","how":{"ask":"The same volume per second passes the arterioles and the capillaries. How fast must it move through twenty times the total area?","know":"• **Continuity: Q = A·v** (Q = flow rate in cm³/s, A = cross-sectional area, v = mean speed). For blood, Q is the same at every level of the circulation.\n• Vessels in parallel: use their **combined** area.\n• Larger total A → smaller v. Capillaries have the largest total area, so blood is slowest there.","steps":[{"text":"Find the flow rate in the arterioles.","hl":"2.0 cm/s through arterioles with a combined cross-sectional area of 40 cm²","calc":["Q = A × v","Q = 40 cm² × 2.0 cm/s = **80 cm³/s**"]},{"text":"The same Q passes the capillaries; divide by their total area.","hl":"total 800 cm²","calc":["v = Q ÷ A = 80 cm³/s ÷ 800 cm²","v = **0.10 cm/s**","area × 20 → speed ÷ 20"],"chart":{"type":"line","caption":"Same flow (80 cm³/s): speed falls as total area grows","x":{"label":"Total cross-sectional area (cm²)","min":0,"max":800,"step":200},"y":{"label":"Mean speed (cm/s)","min":0,"max":2,"step":0.5},"series":[{"name":"v = Q ÷ A","marker":"circle","line":"smooth","points":[[40,2],[80,1],[160,0.5],[400,0.2],[800,0.1]]}]}},{"text":"2.0 cm/s assumes equal flow means equal speed. 40 cm/s treats the thin capillaries like a nozzle and multiplies by 20. 0.0025 cm/s divides the arteriole speed by the capillary area and skips Q.","strike":["2.0 cm/s","40 cm/s","0.0025 cm/s"]},{"text":"Answer: 0.10 cm/s."}],"trap":"Thinking narrow vessels speed blood up. One narrow tube would, but the blood is split among countless capillaries whose combined area is far larger than the arterioles'."},"teach":[{"text":"First, **find every number** and what it is.","marks":[{"t":"2.0 cm/s","note":"arteriole speed"},{"t":"40 cm²","note":"arteriole total area"},{"t":"800 cm²","note":"capillary total area"}]},{"text":"**Continuity:** blood is not lost between levels, so the volume per second is the same everywhere.","calc":["Q = A·v = constant"]},{"text":"**Combined area decides the speed.** More total area for the same Q means slower blood.","calc":["v = Q ÷ A"],"chart":{"type":"line","caption":"Speed versus total area at a fixed flow of 80 cm³/s","x":{"label":"Total cross-sectional area (cm²)","min":0,"max":800,"step":200},"y":{"label":"Mean speed (cm/s)","min":0,"max":2,"step":0.5},"series":[{"name":"v = Q ÷ A","marker":"circle","line":"smooth","points":[[40,2],[80,1],[160,0.5],[400,0.2],[800,0.1]]}]}},{"text":"**Rule to reuse:** Q = A·v is the same at every level, so speed is smallest where the total cross-sectional area is largest: the capillaries."}]},
  {"id":"cpt-pe1-27a","s":"Electrochemistry & Redox","disc":"gen_chem","aamc":"4E","skill":"SIRS 4","from":["pe1-cp:27#1","pe1-cp:27#2","pe1-cp:27#3"],"q":"On a potential–pH diagram, the boundary between Cu²⁺ and copper metal stays at +0.34 V from pH 0 to 5. Which species is absent from its half-reaction?","choices":["H⁺ and OH⁻","The two electrons","The Cu²⁺ ions","The copper metal"],"ans":0,"exp":"A **horizontal** boundary keeps the same potential whatever the pH, so the equilibrium **does not depend on pH**: its half-reaction, Cu²⁺ + 2e⁻ ⇌ Cu, contains **no H⁺ or OH⁻**. It still transfers electrons, and both copper forms appear in it.","how":{"ask":"Decide what a boundary at one fixed potential across a range of pH says about the half-reaction.","know":"• Pourbaix diagram: potential E (y) versus pH (x); each line is an equilibrium between two forms.\n• **Horizontal line**: E does not change with pH → **pH-independent** → no H⁺ or OH⁻ in the half-reaction, but electrons are transferred.","steps":[{"text":"The boundary is flat: one potential across several pH values.","hl":"stays at +0.34 V from pH 0 to 5","calc":["E constant while pH changes → pH-independent"]},{"text":"Write the half-reaction it represents.","calc":["Cu²⁺ + 2e⁻ ⇌ Cu   (E° = +0.34 V)","no H⁺, no OH⁻"],"chart":{"type":"line","caption":"Boundary lines on a simplified iron potential–pH diagram","x":{"label":"pH","min":0,"max":8,"step":1},"y":{"label":"Potential (V)","min":-0.8,"max":1.2,"step":0.4},"series":[{"name":"Fe³⁺/Fe²⁺: horizontal","marker":"circle","line":"straight","points":[[0,0.77],[2,0.77]]},{"name":"Fe³⁺/Fe(OH)₃: vertical","marker":"square-open","line":"straight","points":[[2,0.77],[2,1.2]]},{"name":"Fe(OH)₃/Fe²⁺","marker":"diamond","line":"straight","points":[[2,0.77],[8,-0.29]]},{"name":"Fe²⁺/Fe: horizontal","marker":"triangle","line":"straight","points":[[0,-0.44],[8,-0.44]]}]}},{"text":"A line set at a potential is a redox couple, so electrons must be in it; Cu²⁺ and Cu are the two forms the line separates.","strike":["The two electrons","The Cu²⁺ ions","The copper metal"]},{"text":"Answer: H⁺ and OH⁻."}],"trap":"Thinking a flat line means \"no electrons\": that describes a vertical line. A flat line is a redox couple with no H⁺ or OH⁻."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"potential–pH diagram","note":"E on y, pH on x"},{"t":"stays at +0.34 V","note":"horizontal line"},{"t":"from pH 0 to 5","note":"pH changes, E does not"}]},{"text":"**Read the slope of each boundary.** A flat line sits at one potential, whatever the pH.","chart":{"type":"line","caption":"Boundary lines on a simplified iron potential–pH diagram","x":{"label":"pH","min":0,"max":8,"step":1},"y":{"label":"Potential (V)","min":-0.8,"max":1.2,"step":0.4},"series":[{"name":"Fe³⁺/Fe²⁺: horizontal","marker":"circle","line":"straight","points":[[0,0.77],[2,0.77]]},{"name":"Fe³⁺/Fe(OH)₃: vertical","marker":"square-open","line":"straight","points":[[2,0.77],[2,1.2]]},{"name":"Fe(OH)₃/Fe²⁺","marker":"diamond","line":"straight","points":[[2,0.77],[8,-0.29]]},{"name":"Fe²⁺/Fe: horizontal","marker":"triangle","line":"straight","points":[[0,-0.44],[8,-0.44]]}]}},{"text":"**Flat = pH has no say.** If changing pH does not move the line, H⁺ and OH⁻ are not in the equilibrium.","calc":["horizontal → electrons yes, H⁺/OH⁻ no"]},{"text":"**Also:** a vertical Pourbaix boundary means the equilibrium depends on pH but transfers no electrons."},{"text":"**Also:** the higher a region lies on a potential–pH diagram, the more oxidized the species stable there."},{"text":"**Rule to reuse:** a horizontal Pourbaix boundary is a redox equilibrium that does not depend on pH (no H⁺ or OH⁻ involved)."}]},
  {"id":"cpt-pe1-28a","s":"Molecular Structure & Intermolecular Forces","disc":"gen_chem","aamc":"5B","skill":"SIRS 1","from":["pe1-cp:28#1"],"q":"Sulfur hexafluoride, SF₆, has six fluorine atoms bonded to a central sulfur atom that carries no lone pairs. Which hybridization describes the sulfur?","choices":["sp³d²","sp³d³","dsp³","sp²"],"ans":0,"exp":"Six bonded atoms and no lone pairs = **6 electron domains**, so sulfur needs **6 hybrid orbitals**: sp³d² (1 s + 3 p + 2 d = 6), which point to the corners of an octahedron. d²sp³ is the same count, written when inner d orbitals mix in a metal complex. sp³d³ makes 7, dsp³ (another name for sp³d) makes 5, and sp² makes 3.","how":{"ask":"Count sulfur's electron domains, then pick the hybridization label that makes exactly that many orbitals.","know":"• Hybrid orbitals needed = electron domains (bonded atoms + lone pairs).\n• **2 → sp; 3 → sp²; 4 → sp³ (tetrahedral); 5 → sp³d (trigonal bipyramidal); 6 → sp³d² or d²sp³ (octahedral)**.\n• Count the orbitals in a label: s = 1, then read each superscript for p and d (no superscript = 1).","steps":[{"text":"Count sulfur's domains: six bonds and no lone pairs.","hl":"six fluorine atoms bonded to a central sulfur atom that carries no lone pairs","calc":["domains = 6 bonds + 0 lone pairs = **6**","6 domains → **6** hybrid orbitals → octahedral"]},{"text":"Count the orbitals each label makes.","calc":["sp³d²: 1 + 3 + 2 = **6** → octahedral","sp³d³: 1 + 3 + 3 = 7 → pentagonal bipyramidal","dsp³: 1 + 1 + 3 = 5 → trigonal bipyramidal","sp²: 1 + 2 = 3 → trigonal planar"]},{"text":"Seven orbitals is one too many, and five or three cannot hold six bonds.","strike":["sp³d³","dsp³","sp²"]},{"text":"Answer: sp³d²."}],"trap":"dsp³ also uses a d orbital, so it looks right for an expanded octet, but it makes only 5 hybrid orbitals: the trigonal bipyramidal set of PCl₅, not the octahedral set of SF₆."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"six fluorine atoms","note":"6 bonded atoms"},{"t":"no lone pairs","note":"0 extra domains"},{"t":"hybridization","note":"how many orbitals mix"}]},{"text":"**Electron domains** = atoms bonded + lone pairs. Each domain needs one hybrid orbital.","calc":["SF₆: 6 + 0 = 6 domains → 6 orbitals"]},{"text":"**Match the count to a label.**","calc":["4 → sp³ (CH₄, tetrahedral)","5 → sp³d (PCl₅, trigonal bipyramidal)","6 → sp³d² or d²sp³ (SF₆, octahedral)"]},{"text":"**Rule to reuse:** 6 domains → octahedral → sp³d² (d²sp³ in metal complexes); 5 → sp³d; 4 → sp³."}]},
  {"id":"cpt-pe1-29b","s":"Stoichiometry & Solutions","disc":"gen_chem","aamc":"4B","skill":"SIRS 1","from":["pe1-cp:29#2","pe1-cp:29#1"],"q":"A sealed flask holds 2.00 mol of nitrogen gas at STP. Assuming ideal behavior, what volume does the gas occupy?","choices":["44.8 L","48.9 L","11.2 L","89.6 L"],"ans":0,"exp":"At **STP (0 °C = 273 K, 1 atm)** one mole of ideal gas fills **22.4 L**, so V = 2.00 mol × 22.4 L/mol = **44.8 L**. 48.9 L is what the sample would fill at 298 K (room temperature), not at STP; 11.2 L divides by 2 instead of multiplying; 89.6 L uses 4 mol, counting the two N atoms in each N₂ as separate moles.","how":{"ask":"What is the molar volume at STP, and how many moles are in the flask?","know":"• **STP = 0 °C (273 K) and 1 atm**. At STP, 1 mol of ideal gas occupies **22.4 L**.\n• 22.4 L/mol holds only at 0 °C; at 25 °C (298 K) a mole fills about 24.5 L.\n• Check with PV = nRT: V = nRT/P.","steps":[{"text":"Note the amount and the conditions.","hl":"2.00 mol of nitrogen gas at STP","calc":["n = 2.00 mol","STP: T = 273 K, P = 1 atm"]},{"text":"Use the molar volume at STP.","calc":["V = n × 22.4 L/mol","V = 2.00 mol × 22.4 L/mol","V = **44.8 L**"]},{"text":"Check with PV = nRT.","calc":["V = nRT ÷ P","V = (2.00 mol)(0.0821 L·atm·mol⁻¹·K⁻¹)(273 K) ÷ 1 atm","V = **44.8 L** ✓"]},{"text":"48.9 L uses 298 K (25 °C), room temperature, which is not STP.","calc":["(2.00)(0.0821)(298) ÷ 1 = 48.9 L"],"strike":["48.9 L"]},{"text":"11.2 L divides 22.4 by 2 instead of multiplying.","calc":["22.4 ÷ 2 = 11.2 L"],"strike":["11.2 L"]},{"text":"89.6 L uses 4 mol, counting the two N atoms in each N₂ as separate moles.","calc":["(2.00 × 2) mol × 22.4 L/mol = 89.6 L"],"strike":["89.6 L"]},{"text":"Answer: 44.8 L."}],"trap":"Using 24.5 L/mol, the molar volume at 25 °C, gives 48.9 L. The 22.4 L/mol shortcut belongs to 0 °C only."},"teach":[{"text":"First, **find every number** and what it stands for.","marks":[{"t":"2.00 mol","note":"n"},{"t":"STP","note":"0 °C and 1 atm"},{"t":"ideal behavior","note":"use the molar volume"}]},{"text":"**STP** means standard temperature and pressure: **0 °C (273 K) and 1 atm**. There, one mole of any ideal gas fills **22.4 L**.","calc":["at STP: 1 mol ↔ 22.4 L"]},{"text":"**Temperature matters.** Volume grows with T, so at 25 °C a mole fills more.","calc":["0 °C: 22.4 L/mol","25 °C: 22.4 × 298/273 ≈ 24.5 L/mol"]},{"text":"**Also:** a gas is most ideal at high T and low P, where particle volume and intermolecular forces are both negligible."},{"text":"**Rule to reuse:** V = n × 22.4 L/mol only at STP (0 °C, 1 atm); at any other temperature use PV = nRT."}]},
  {"id":"cpt-pe1-30a","s":"Light & Optics","disc":"organic_chem","aamc":"4D","skill":"SIRS 2","from":["pe1-cp:30#1"],"q":"A deep-sea fish sees with a single visual pigment that absorbs most strongly at 490 nm. Which change would most directly give it color vision?","choices":["A pigment with another peak","Twice as much of its pigment","A peak shifted to 550 nm","A narrower absorption band"],"ans":0,"exp":"One pigment only counts absorbed photons, so a dim light at 490 nm and a brighter light elsewhere can give the **same signal**. A **second pigment with a different absorption peak** responds differently to each wavelength, and the brain **compares the two responses** to tell colors apart.","how":{"ask":"With one pigment, can the brain tell a change in color from a change in brightness? What would let it compare?","know":"• A photoreceptor reports only how many photons it absorbs, not their wavelength (**univariance**).\n• **Color vision** needs at least two pigments with **different absorption peaks**; the brain compares their responses (their ratio).\n• More pigment, a shifted peak or a narrower band still leaves one pigment, so still no comparison.","steps":[{"text":"With one pigment, 450-nm and 530-nm light are absorbed equally well, so after matching brightness they give identical signals.","hl":"a single visual pigment","calc":["one pigment → one number (photons absorbed)","color and brightness mixed together"]},{"text":"More pigment raises sensitivity; a shifted peak or a narrower band changes which light is absorbed best. Each still leaves one pigment and one signal.","strike":["Twice as much of its pigment","A peak shifted to 550 nm","A narrower absorption band"]},{"text":"Add a second pigment peaking elsewhere: the two pigments now absorb in a different ratio at each wavelength.","calc":["450 nm: first 0.7, second ≈ 0.0","530 nm: first 0.7, second 0.7","different ratios → different colors"],"chart":{"type":"line","caption":"The fish pigment and a second pigment with another peak","x":{"label":"Wavelength (nm)","min":400,"max":650,"step":50},"y":{"label":"Relative absorbance","min":0,"max":1,"step":0.2},"series":[{"name":"Fish pigment (490 nm)","marker":"circle","line":"smooth","points":[[400,0.1],[430,0.4],[450,0.7],[470,0.92],[490,1],[510,0.92],[530,0.7],[550,0.4],[580,0.1],[600,0.03]]},{"name":"Second pigment (560 nm)","marker":"square-open","line":"smooth","points":[[450,0.01],[480,0.1],[510,0.4],[530,0.7],[545,0.92],[560,1],[575,0.92],[590,0.7],[610,0.4],[640,0.1]]}]}},{"text":"Answer: a pigment with another peak."}],"trap":"Choosing more pigment: it makes the fish more sensitive in dim light, but one pigment, however much of it, cannot separate color from brightness."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"a single visual pigment","note":"only one kind"},{"t":"490 nm","note":"its absorption peak"},{"t":"color vision","note":"telling wavelengths apart"}]},{"text":"**One pigment sends one number:** photons absorbed. A dim light near the peak and a bright light off the peak can give the same number.","calc":["signal = brightness × absorbance"]},{"text":"**Two pigments with different peaks** absorb each wavelength in a different ratio; the brain compares them.","chart":{"type":"line","caption":"Two pigments, two peaks","x":{"label":"Wavelength (nm)","min":400,"max":650,"step":50},"y":{"label":"Relative absorbance","min":0,"max":1,"step":0.2},"series":[{"name":"Fish pigment (490 nm)","marker":"circle","line":"smooth","points":[[400,0.1],[430,0.4],[450,0.7],[470,0.92],[490,1],[510,0.92],[530,0.7],[550,0.4],[580,0.1],[600,0.03]]},{"name":"Second pigment (560 nm)","marker":"square-open","line":"smooth","points":[[450,0.01],[480,0.1],[510,0.4],[530,0.7],[545,0.92],[560,1],[575,0.92],[590,0.7],[610,0.4],[640,0.1]]}]}},{"text":"**Rule to reuse:** color vision comes from comparing the responses of pigments with different absorption peaks; one pigment alone cannot tell wavelength from brightness."}]},
  {"id":"cpt-pe1-31a","s":"Amino Acids & Proteins","disc":"gen_chem","aamc":"5B","skill":"SIRS 2","from":["pe1-cp:31#1","pe1-cp:31#2"],"q":"An insect odorant-binding protein holds a small hydrocarbon odorant inside a buried cavity. Which residue would most likely line that cavity?","choices":["Valine","Glutamate","Arginine","Threonine"],"ans":0,"exp":"A hydrocarbon odorant is **nonpolar**, so it binds best in a **hydrophobic pocket** whose side chains are also hydrocarbon. Valine's isopropyl group is all C and H and packs against the odorant (like dissolves like). Glutamate (–COO⁻) and arginine (guanidinium, +) are charged, and threonine's –OH is polar; all three would rather face water.","how":{"ask":"Is the odorant polar or nonpolar, and which side chain is itself pure hydrocarbon?","know":"• **Nonpolar side chains** (hydrophobic): Ala, **Val, Leu, Ile**, Met, **Phe**, Trp, Pro.\n• **Polar uncharged**: Ser, **Thr**, Asn, Gln, Tyr, Cys. **Charged**: Asp, **Glu** (−); Lys, **Arg**, His (+).\n• Like dissolves like: a hydrocarbon ligand is buried among hydrocarbon side chains.","steps":[{"text":"The ligand is a hydrocarbon: only C and H, so it is nonpolar.","hl":"a small hydrocarbon odorant","calc":["C–H bonds share electrons almost evenly → **nonpolar**"]},{"text":"It sits in a buried cavity, away from water, so the lining must be hydrophobic too.","hl":"inside a buried cavity"},{"text":"Valine's side chain is all C and H: it fits.","calc":["Val: –CH(CH₃)₂ → nonpolar ✓"]},{"text":"Glutamate carries –COO⁻ and arginine a positive guanidinium at pH 7: charges want water. Threonine's –OH is polar.","strike":["Glutamate","Arginine","Threonine"]},{"text":"Answer: valine."}],"trap":"Threonine looks harmless because it is small and uncharged, but its –OH makes it polar; a pocket for a pure hydrocarbon is lined with Leu, Ile, Val and Phe."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"hydrocarbon odorant","note":"only C and H → nonpolar"},{"t":"buried cavity","note":"away from water"},{"t":"line that cavity","note":"side chains facing the ligand"}]},{"text":"**Polar vs nonpolar:** O and N pull electrons and make polar or charged groups; C–H bonds are nonpolar. Hydrocarbons mix with hydrocarbons, not with water."},{"text":"**The hydrophobic four** to remember for pockets: side chains made only of carbon and hydrogen.","calc":["Leu: –CH₂CH(CH₃)₂","Ile: –CH(CH₃)CH₂CH₃","Val: –CH(CH₃)₂","Phe: –CH₂C₆H₅"]},{"text":"**Also:** charged or polar side chains don't fit a pocket for a nonpolar ligand; swapping in Asp, Glu, Lys, Arg, Ser or Thr weakens binding."},{"text":"**Rule to reuse:** a nonpolar ligand binds in a hydrophobic pocket lined with Leu, Ile, Val and Phe."}]},
  {"id":"cpt-pe1-32a","s":"Enzymes & Kinetics","disc":"biochemistry","aamc":"5E","skill":"SIRS 1","from":["pe1-cp:32#1","pe1-cp:32#2"],"q":"ATP is synthesized with ³³P in its β-phosphate only. After hexokinase converts glucose to glucose 6-phosphate with this ATP, where is the label found?","choices":["In ADP","In glucose 6-phosphate","In free phosphate","In AMP"],"ans":0,"exp":"Hexokinase, like every kinase, transfers ATP's **terminal (γ) phosphate** to its substrate. The **α and β phosphates stay** behind as ADP, so a label on β ends up in **ADP**, not in glucose 6-phosphate.","how":{"ask":"Find which of ATP's three phosphates the kinase moves, then see where the β phosphate ends up.","know":"• ATP phosphates, from the ribose outward: **α, β, γ**.\n• Kinase: ATP + R–OH → **ADP + R–O–PO₃²⁻**; only **γ** moves.\n• ADP keeps α and β; AMP would keep only α.","steps":[{"text":"The label is on β, the middle phosphate.","hl":"³³P in its β-phosphate only"},{"text":"Write the kinase reaction.","calc":["glucose + ATP(α–β*–γ) → glucose–O–P(γ) + ADP(α–β*)","label (*) stays in **ADP**"]},{"text":"Only γ reaches the glucose, and no phosphate is released free.","strike":["In glucose 6-phosphate","In free phosphate"]},{"text":"AMP would form only if β and γ left together, which a kinase does not do.","strike":["In AMP"]},{"text":"Answer: in ADP."}],"trap":"Assuming any phosphorus label in ATP is passed on: a kinase moves only the γ phosphate."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"β-phosphate","note":"the middle one"},{"t":"hexokinase","note":"a kinase"},{"t":"glucose 6-phosphate","note":"gets one phosphate"}]},{"text":"**Name ATP's phosphates** from the sugar out: α, β, γ.","fig":"atp"},{"text":"**A kinase moves the end one.** The γ phosphate goes to the substrate; α and β stay as ADP.","calc":["ATP → ADP + γ-phosphate (to substrate)"]},{"text":"**Also:** a kinase is the catalyst; the phosphate it attaches comes from ATP's γ phosphate."},{"text":"**Rule to reuse:** kinases transfer ATP's γ (terminal) phosphate; any label on α or β stays in ADP."}]},
  {"id":"cpt-pe1-33a","s":"Molecular Structure & Intermolecular Forces","disc":"gen_chem","aamc":"5B","skill":"SIRS 1","from":["pe1-cp:33#1","pe1-cp:33#2"],"q":"In 1,2-dichloroethene, ClHC=CHCl, each carbon of the double bond is bonded to three atoms and has no lone pairs. What are its hybridization and geometry?","choices":["sp²; trigonal planar","sp³; trigonal pyramidal","sp³; tetrahedral","sp; linear"],"ans":0,"exp":"Three bonded atoms and no lone pairs give **three domains**, so each alkene carbon is **sp²**: trigonal planar with 120° angles. The one p orbital left unmixed on each carbon forms the π bond of C=C. sp³ needs four domains (tetrahedral, or trigonal pyramidal with a lone pair); sp needs two (linear).","how":{"ask":"Count the electron domains on an alkene carbon and convert them to a hybridization and shape.","know":"• Electron domains = bonded atoms + lone pairs (a double bond counts once).\n• **4 → sp³**, tetrahedral, 109.5° (with one lone pair: trigonal pyramidal); **3 → sp²**, trigonal planar, 120°; **2 → sp**, linear, 180°.","steps":[{"text":"Count the domains on one alkene carbon.","hl":"bonded to three atoms and has no lone pairs","calc":["domains = 3 atoms (Cl, H, C) + 0 lone pairs = **3**"]},{"text":"Three domains → three sp² hybrid orbitals, spread as far apart as possible in one plane.","calc":["3 domains → **sp²**","angles ≈ 120° → **trigonal planar**"]},{"text":"sp³ needs four domains: tetrahedral with four atoms, trigonal pyramidal with three atoms plus a lone pair. These carbons have neither.","strike":["sp³; trigonal pyramidal","sp³; tetrahedral"]},{"text":"sp needs only two domains, as in a C≡C or C≡N carbon.","strike":["sp; linear"]},{"text":"Answer: sp²; trigonal planar."}],"trap":"sp³; trigonal pyramidal also has three atoms around the center, but that shape needs a fourth domain, a lone pair, which these alkene carbons do not have."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"ClHC=CHCl","note":"C=C double bond"},{"t":"three atoms","note":"3 bonded groups"},{"t":"no lone pairs","note":"nothing extra"}]},{"text":"**Electron domains** are the regions of electrons around an atom: each bonded atom counts once (single, double or triple bond), and each lone pair counts once."},{"text":"**Domains → hybridization → shape.**","calc":["2 → sp → linear","3 → sp² → trigonal planar","4 → sp³ → tetrahedral"]},{"text":"**Also:** cis/trans isomers exist because a C=C cannot rotate without breaking its π bond."},{"text":"**Rule to reuse:** each carbon of a C=C has 3 domains, so it is sp² and trigonal planar (120°)."}]},
  {"id":"cpt-pe1-34b","s":"Carbohydrates, Lipids & Nucleic Acids","disc":"biochemistry","aamc":"5E","skill":"SIRS 1","from":["pe1-cp:34#2","pe1-cp:34#1"],"q":"Pancreatic lipase digests a dietary triacylglycerol made of three oleic acid chains. Which final products does the enzyme release?","choices":["Two fatty acids; 2-monoacylglycerol","Three fatty acids; glycerol","One fatty acid; 1,2-diacylglycerol","Two fatty acids; 1-monoacylglycerol"],"ans":0,"exp":"Pancreatic lipase cuts only the esters at **positions 1 and 3** of glycerol. Two cuts free **two oleic acids**, and the acyl chain at **C2** stays on: a **2-monoacylglycerol**. Glycerol would need three cuts and a diacylglycerol only one, and a 1-monoacylglycerol would mean the middle ester had been cut.","how":{"ask":"Use the enzyme's position rule to count the cuts and see which chain stays on glycerol.","know":"• Glycerol carbons: C1 and C3 are the ends; C2 is the middle.\n• **Pancreatic lipase** hydrolyzes the **C1 and C3** esters only.\n• Products: **2 fatty acids + 2-monoacylglycerol** (named for the carbon still holding a chain).","steps":[{"text":"The enzyme is pancreatic lipase, which works at the end positions.","hl":"Pancreatic lipase"},{"text":"Apply the position rule.","calc":["cut C1 ester → 1 oleic acid","cut C3 ester → 1 oleic acid","C2 ester kept → **2-monoacylglycerol**","total: **2** fatty acids"]},{"text":"Three cuts or one cut does not match the two end positions.","strike":["Three fatty acids; glycerol","One fatty acid; 1,2-diacylglycerol"]},{"text":"A chain left on C1 would mean the middle ester was cut, which this enzyme does not do.","strike":["Two fatty acids; 1-monoacylglycerol"]},{"text":"Answer: two fatty acids and a 2-monoacylglycerol."}],"trap":"Assuming digestion goes all the way to glycerol: pancreatic lipase leaves the middle chain in place."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"Pancreatic lipase","note":"cuts C1 and C3"},{"t":"three oleic acid chains","note":"three esters to start"}]},{"text":"**Number glycerol's carbons** 1, 2, 3; each holds one ester.","fig":"triacylglycerol"},{"text":"**Cut only the ends.** Two acids leave; the middle chain stays.","calc":["3 chains − 2 cut = 1 left, on C2"]},{"text":"**Also:** lipases hydrolyze the ester bonds of triacylglycerols, releasing free fatty acids."},{"text":"**Rule to reuse:** pancreatic lipase hydrolyzes positions 1 and 3, giving two fatty acids and a 2-monoacylglycerol."}]},
  {"id":"cpt-pe1-35b","s":"Amino Acids & Proteins","disc":"biochemistry","aamc":"5D","skill":"SIRS 2","from":["pe1-cp:35#2","pe1-cp:35#1"],"q":"Four residues of a soluble protein are replaced: Lys→Glu, Arg→Asp, Lys→Asp and Ala→His. What is the change in the protein's net charge at pH 7?","choices":["A decrease of 6","A decrease of 5","No change","An increase of 6"],"ans":0,"exp":"At pH 7, Lys and Arg are **+1**, Glu and Asp are **−1**, and Ala and His are **≈ 0**. Each basic-to-acidic swap goes from +1 to −1, a change of **−2**; there are three of them. Ala→His changes nothing. Total: −2 − 2 − 2 + 0 = **−6**.","how":{"ask":"For each substitution, subtract the old side-chain charge from the new one at pH 7, then add the four changes.","know":"• Charges at pH 7: Arg/Lys **+1**, Asp/Glu **−1**, His **≈ 0**, others **0**.\n• Change at each site = **new − old**.\n• Net change = sum of the site changes.","steps":[{"text":"List the swaps.","hl":"Lys→Glu, Arg→Asp, Lys→Asp and Ala→His"},{"text":"Compute new − old at each site.","fig":["lysine-sc","arginine-sc","glutamate","aspartate-sc","histidine-sc"],"calc":["Lys→Glu: (−1) − (+1) = **−2**","Arg→Asp: (−1) − (+1) = **−2**","Lys→Asp: (−1) − (+1) = **−2**","Ala→His: 0 − 0 = **0**"]},{"text":"Add them.","calc":["Δ = −2 + (−2) + (−2) + 0 = **−6**"]},{"text":"Counting His as +1 gives −2 − 2 − 2 + 1 = −5, but at pH 7 His is ≈ 0.","strike":["A decrease of 5"]},{"text":"Seeing three charged residues swapped for three charged residues as no change ignores the sign: each swap trades +1 for −1, a change of −2.","strike":["No change"]},{"text":"Positive charges are replaced by negative ones, so the net charge falls; an increase has the sign flipped.","strike":["An increase of 6"]},{"text":"Answer: a decrease of 6 (Δ = −6)."}],"trap":"Counting His as +1 at pH 7: its side-chain pKa is about 6, so at pH 7 it is mostly neutral and Ala→His adds nothing."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"Four residues","note":"four sites to add"},{"t":"pH 7","note":"use pH 7 charges"},{"t":"net charge","note":"sum of changes"}]},{"text":"**Assign charges at pH 7.**","calc":["Lys, Arg: +1","Glu, Asp: −1","Ala, His: 0"]},{"text":"**Change per site = new − old.** A + → − swap is worth 2.","calc":["(−1) − (+1) = −2"]},{"text":"**Also:** at pH 7, count Arg and Lys as +1, Asp and Glu as −1, and His and everything else as 0."},{"text":"**Rule to reuse:** for each substitution take new charge minus old charge at the stated pH, then add all the site changes."}]},
  {"id":"cpt-pe1-36a","s":"Reading Data","disc":"biochemistry","aamc":"5D","skill":"SIRS 4","from":["pe1-cp:36#1","pe1-cp:36#2"],"q":"After 15 min at 55 °C and cooling, wild-type lipase kept 30% of its activity, mutant A kept 65% and mutant B kept 25%. Which conclusion fits?","choices":["Only mutant A is more stable","Both mutants are more stable","Only mutant B is more stable","Neither mutant is more stable"],"ans":0,"exp":"Retained activity is the measure of heat stability: more activity left means less damage. Mutant A kept **65% vs the wild type's 30%**, so it is more stable. Mutant B kept **25%**, slightly **less** than the wild type, so it is not more stable.","how":{"ask":"Line up each mutant's retained activity against the wild type's and decide which are higher.","know":"• **% activity kept after heating**: higher → more heat-stable.\n• Compare every variant with the **wild type**, the reference.\n• A conclusion about \"both\" fails if even one variant does not fit.","steps":[{"text":"Find the reference and each variant's value.","hl":"wild-type lipase kept 30% of its activity, mutant A kept 65% and mutant B kept 25%"},{"text":"Compare each with the wild type.","chart":{"type":"bar","caption":"Activity kept after heating","x":{"label":"Enzyme"},"y":{"label":"Activity kept (%)","min":0,"max":100,"step":20},"categories":["Wild type","Mutant A","Mutant B"],"series":[{"name":"Kept","values":[30,65,25]}]},"calc":["A: 65% > 30% → **more stable**","B: 25% ≤ 30% → **not more stable**"]},{"text":"Mutant B kept less than the wild type, so it is neither more stable alone nor along with A.","strike":["Both mutants are more stable","Only mutant B is more stable"]},{"text":"Mutant A clearly kept more, so it is wrong that neither is more stable.","strike":["Neither mutant is more stable"]},{"text":"Answer: only mutant A is more stable."}],"trap":"Assuming every mutant behaves alike: check each one against the wild type separately."},"teach":[{"text":"First, **find every number** and what it is.","marks":[{"t":"55 °C","note":"heating step"},{"t":"30%","note":"wild type, the reference"},{"t":"65%","note":"mutant A"},{"t":"25%","note":"mutant B"}]},{"text":"**Heat, cool, assay.** The activity that survives measures how well the enzyme resists heat.","calc":["% kept ↑ → heat stability ↑"]},{"text":"**Subtract the reference.**","calc":["A: 65 − 30 = +35","B: 25 − 30 = −5"]},{"text":"**Also:** keep only the claim the numbers show; reject absolute words like all, fully or every when any activity remains."},{"text":"**Rule to reuse:** compare each variant's retained activity with the wild type's; higher means more heat-stable, lower means less."}]},
  {"id":"cpt-pe1-37a","s":"Acids & Bases","disc":"gen_chem","aamc":"5A","skill":"SIRS 2","from":["pe1-cp:37#1"],"q":"A urine sample from patient A has a pH of 5.8, and a sample from patient B has a pH of 7.8. How does [H⁺] in sample B compare with sample A?","choices":["100 times lower","100 times higher","2 times lower","20 times lower"],"ans":0,"exp":"Because **pH = −log[H⁺]**, one pH unit corresponds to a **tenfold** change in [H⁺]. Sample B is 7.8 − 5.8 = 2 units higher, so its [H⁺] is 10² = **100 times lower**: about 1.6 × 10⁻⁸ M versus 1.6 × 10⁻⁶ M.","how":{"ask":"Find the pH difference, turn it into a power of ten, and decide whether a higher pH means more or less H⁺.","know":"• **pH = −log[H⁺]** → [H⁺] = 10^(−pH).\n• A difference of Δ pH units = a factor of **10^Δ** in [H⁺].\n• **Higher pH = less H⁺**.","steps":[{"text":"Find the pH change from A to B.","hl":"a pH of 5.8","calc":["ΔpH = 7.8 − 5.8 = **2** units"]},{"text":"Convert to a factor and check with real concentrations.","hl":"a pH of 7.8","calc":["factor = 10² = **100**","pH 5.8: [H⁺] = 10^−5.8 ≈ 1.6 × 10⁻⁶ M","pH 7.8: [H⁺] = 10^−7.8 ≈ 1.6 × 10⁻⁸ M","1.6 × 10⁻⁶ ÷ 1.6 × 10⁻⁸ = **100**"],"strike":["2 times lower","20 times lower"]},{"text":"Direction: B has the higher pH, so it has less H⁺.","strike":["100 times higher"]},{"text":"Answer: 100 times lower."}],"trap":"\"2 times lower\" treats pH as linear; every pH unit is a tenfold change, so 2 units is 10 × 10 = 100."},"teach":[{"text":"First, **find the numbers** and what you must compare.","marks":[{"t":"a pH of 5.8","note":"sample A"},{"t":"a pH of 7.8","note":"sample B"},{"t":"[H⁺]","note":"H⁺ concentration"}]},{"text":"**pH counts powers of ten:** [H⁺] = 10^(−pH).","calc":["pH 5 → 10⁻⁵ M","pH 6 → 10⁻⁶ M (10 times less)"]},{"text":"**Subtract, then raise 10 to that power.** Then set the direction: higher pH, less H⁺.","calc":["factor = 10^(ΔpH)"]},{"text":"**Rule to reuse:** a change of Δ pH units changes [H⁺] by a factor of 10^Δ, and a lower pH means more H⁺."}]},
  {"id":"cpt-pe1-38b","s":"Carbohydrates, Lipids & Nucleic Acids","disc":"biochemistry","aamc":"5D","skill":"SIRS 1","from":["pe1-cp:38#2","pe1-cp:38#1","pe1-cp:38#3"],"q":"A glucopyranose has a phosphate on the ring carbon that is bonded to C5 but not to the ring oxygen. What is the compound?","choices":["Glucose 4-phosphate","Glucose 6-phosphate","Glucose 3-phosphate","Glucose 1-phosphate"],"ans":0,"exp":"C5 is bonded to the ring O, to **C6** (the –CH₂OH outside the ring) and to **C4**. The only other **ring** carbon on C5 is C4, so the phosphate is on C4: **glucose 4-phosphate**. A sugar phosphate is named by the number of the carbon that holds the phosphate.","how":{"ask":"Which ring carbon is next to C5 on the side away from the ring O, and what number is it?","know":"• Ring order: O – C1 – C2 – C3 – C4 – C5 – O.\n• C5's neighbors: ring O, C4 (ring), C6 (outside).\n• Name = glucose **n**-phosphate, where n is the carbon carrying the phosphate.","steps":[{"text":"The clue locates the phosphate relative to C5.","hl":"bonded to C5 but not to the ring oxygen"},{"text":"List C5's neighbors.","fig":"alpha-glucopyranose","calc":["C5 → ring O, **C4**, C6","ring carbon among them: **C4**"]},{"text":"C6 is bonded to C5 but sits outside the ring, so it is not a ring carbon.","strike":["Glucose 6-phosphate"]},{"text":"C3 is two carbons from C5, and C1 is bonded to the ring O.","strike":["Glucose 3-phosphate","Glucose 1-phosphate"]},{"text":"Answer: glucose 4-phosphate."}],"trap":"Reaching for glucose 6-phosphate because it is the familiar one: C6 is bonded to C5 but is the CH₂OH outside the ring."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"ring carbon","note":"C1–C5 only"},{"t":"bonded to C5","note":"C4 or C6"},{"t":"not to the ring oxygen","note":"rules out C1"}]},{"text":"**Walk the ring.** Every carbon number follows from the ring order.","calc":["O – C1 – C2 – C3 – C4 – C5 – O","C6 hangs off C5"]},{"text":"**Name by carbon number.** The number in a sugar phosphate's name is the carbon bearing the phosphate.","fig":"alpha-glucopyranose"},{"text":"**Also:** in glucopyranose, C1 is anomeric, C2–C4 are ring carbons, C5 is bonded to the ring O, and C6 is the CH₂OH."},{"text":"**Also:** always put the phosphate where the passage says, then number the ring from C1; do not default to C6."},{"text":"**Rule to reuse:** number the ring from C1, find the carbon that carries the phosphate, and name it glucose n-phosphate."}]},
  {"id":"cpt-pe1-39b","s":"Carbohydrates, Lipids & Nucleic Acids","disc":"biochemistry","aamc":"5D","skill":"SIRS 1","from":["pe1-cp:39#2","pe1-cp:39#1","pe1-cp:43#1"],"q":"Glycogen's branching enzyme cuts a short block of glucose residues from a chain end and reattaches it to an interior residue. Which bond attaches the moved block to the interior residue?","choices":["α-1,6","α-1,4","β-1,4","β-1,6"],"ans":0,"exp":"The branching enzyme breaks an α-1,4 bond near the chain end and joins the released block's C1 to the **C6 –OH** of an interior glucose. That **α-1,6** bond is a new branch point. α-1,4 bonds make the linear chain, and glycogen has no β links.","how":{"ask":"When a block is moved to an interior residue to start a branch, which carbon of that residue does it bond to?","know":"• **Branching enzyme**: cuts an α-1,4 bond and forms an **α-1,6** bond (a branch point).\n• **Glycogen synthase**: forms α-1,4 bonds (chain growth).\n• β links appear in cellulose, not glycogen.","steps":[{"text":"The block is moved onto an interior residue: a new branch.","hl":"reattaches it to an interior residue"},{"text":"A branch attaches through C6.","calc":["block C1 → interior C6","→ **α-1,6** branch point"]},{"text":"α-1,4 is the bond that was cut, the linear chain bond made by glycogen synthase.","strike":["α-1,4"]},{"text":"Glycogen is built only from α links.","strike":["β-1,4","β-1,6"]},{"text":"Answer: α-1,6."}],"trap":"Choosing α-1,4 because the block is a piece of chain: inside the block the bonds are α-1,4, but the new bond to the interior residue is α-1,6."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"branching enzyme","note":"makes branch points"},{"t":"interior residue","note":"bonds through C6"}]},{"text":"**Two bonds in glycogen.** α-1,4 runs along a chain; α-1,6 starts a branch.","fig":"alpha-glucopyranose","calc":["chain: C1–O–C4","branch: C1–O–C6"]},{"text":"**The branching enzyme cuts one and makes the other.**","calc":["break α-1,4 → form α-1,6"]},{"text":"**Also:** glycogen synthase forms α-1,4 bonds; the branching enzyme forms α-1,6 bonds."},{"text":"**Also:** branch points are α-1,6 bonds, so fewer branches means fewer α-1,6 bonds."},{"text":"**Rule to reuse:** the branching enzyme forms α-1,6 bonds, one at each branch point."}]},
  {"id":"cpt-pe1-39c","s":"Carbohydrates, Lipids & Nucleic Acids","disc":"biochemistry","aamc":"5D","skill":"SIRS 1","from":["pe1-cp:39#3"],"q":"On a Haworth drawing of a D-glucose residue, its CH₂OH points up while C1's link to the next residue points down. How is this glycosidic link classified?","choices":["α, as in glycogen","β, as in glycogen","α, as in cellulose","β, as in cellulose"],"ans":0,"exp":"For a D-sugar in a Haworth drawing, compare the anomeric (C1) bond with the CH₂OH: **opposite faces → α**, same face → β. Here CH₂OH is up and the C1 bond is down, so the link is **α**, the type found in glycogen and starch. Cellulose uses β links.","how":{"ask":"Is the C1 bond on the same face as the CH₂OH or on the opposite face?","know":"• **D-sugar, Haworth**: C1 substituent **opposite** CH₂OH → **α**; **same** face → **β**.\n• Glycogen and starch: α-1,4 (+ α-1,6). Cellulose: β-1,4.","steps":[{"text":"Read the two directions.","hl":"its CH₂OH points up while C1's link to the next residue points down"},{"text":"Opposite faces → α.","fig":["t1-maltose","t1-cello-beta"],"calc":["CH₂OH up, C1 bond down → opposite → **α**"]},{"text":"β would need the C1 bond on the same face as CH₂OH.","strike":["β, as in glycogen","β, as in cellulose"]},{"text":"Cellulose is built from β links, so an α link is not cellulose's.","strike":["α, as in cellulose"]},{"text":"Answer: α, as in glycogen."}],"trap":"Matching α with cellulose: α links make glycogen and starch; cellulose is β-1,4."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"CH₂OH points up","note":"the reference"},{"t":"C1's link to the next residue points down","note":"the anomeric bond"}]},{"text":"**Compare C1 with CH₂OH.** Opposite faces = α; same face = β.","fig":["alpha-glucopyranose","beta-glucopyranose"]},{"text":"**Match to the polymer.** Glycogen and starch are α-linked; cellulose is β-linked.","calc":["α-1,4: glycogen, starch","β-1,4: cellulose"]},{"text":"**Rule to reuse:** on a Haworth projection, a C1 bond opposite the CH₂OH is α and one on the same face is β."}]},
  {"id":"cpt-pe1-40a","s":"Carbohydrates, Lipids & Nucleic Acids","disc":"biochemistry","aamc":"5D","skill":"SIRS 1","from":["pe1-cp:40#1","pe1-cp:40#2"],"q":"In lactose synthesis, UDP-galactose donates its galactose. Apart from galactose, which sugar ring is part of UDP-galactose?","choices":["Ribofuranose","Deoxyribofuranose","Glucopyranose","Fructofuranose"],"ans":0,"exp":"UDP is **uridine diphosphate**. Uridine is uracil bonded to **ribose**, a five-membered (furanose) ring with –OH groups on C2′ and C3′. UDP is an RNA-type nucleotide, so its sugar is ribose, not deoxyribose; glucose and fructose are not part of it.","how":{"ask":"What does UDP stand for, and which sugar is in that nucleoside?","know":"• **UDP** = uridine diphosphate; **uridine** = uracil + **ribose**.\n• Nucleotides without a \"d\" (ATP, UTP, UDP, CTP) carry **ribose**.\n• Deoxyribose appears in DNA nucleotides (dATP, dTTP…).","steps":[{"text":"The molecule is galactose attached to UDP.","hl":"UDP-galactose"},{"text":"Expand the name.","fig":["uracil","ribose"],"calc":["UDP = uridine diphosphate","uridine = uracil + **ribose** (furanose)"]},{"text":"UDP has no \"d\" prefix, so its sugar keeps the 2′ –OH: it is not deoxyribose.","strike":["Deoxyribofuranose"]},{"text":"Glucose and fructose are not part of a uridine nucleotide.","strike":["Glucopyranose","Fructofuranose"]},{"text":"Answer: ribofuranose."}],"trap":"Picking glucose because UDP-sugars are usually UDP-glucose: the attached sugar varies, but the nucleotide's own sugar is always ribose."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"UDP-galactose","note":"galactose + UDP"},{"t":"Apart from galactose","note":"the nucleotide's sugar"}]},{"text":"**Read UDP.** Uridine diphosphate: uracil + ribose + two phosphates.","fig":"ribose","calc":["U = uridine","D = di (2 phosphates)","P = phosphate"]},{"text":"**Ribose vs deoxyribose.** Ribose has –OH on C2′ and C3′; deoxyribose lacks the 2′ –OH.","fig":["t1-ribose-c2oh","t1-dr-c2"]},{"text":"**Also:** deoxyribose is found in DNA nucleotides such as dTTP; nucleotides without the \"d\" carry ribose."},{"text":"**Rule to reuse:** UDP is uridine diphosphate, and uridine contains ribose."}]},
  {"id":"cpt-pe1-41a","s":"Enzymes & Kinetics","disc":"biochemistry","aamc":"5E","skill":"SIRS 3","from":["pe1-cp:41#1","pe1-cp:41#2"],"q":"A phosphorylated enzyme carries ³²P in its phosphoserines and ³H in its leucines. It is incubated with a protein phosphatase. Which label is lost from the enzyme?","choices":["³²P only","³H only","Both labels","Neither label"],"ans":0,"exp":"A phosphatase **hydrolyzes phosphate esters**, releasing the phosphate as free Pᵢ. The ³²P rides on that phosphate, so it leaves the enzyme. The ³H is built into the leucine side chains, which the phosphatase does not touch, so it stays.","how":{"ask":"Place each label on its chemical group, then ask which group the phosphatase removes.","know":"• **Phosphatase**: R–O–PO₃²⁻ + H₂O → R–OH + Pᵢ (removes phosphate).\n• A radioactive label goes wherever its atom goes.\n• Kinase adds phosphate; phosphatase takes it off.","steps":[{"text":"Locate each label.","hl":"³²P in its phosphoserines and ³H in its leucines","calc":["³²P → phosphate groups","³H → leucine side chains"]},{"text":"The phosphatase cuts off the phosphate.","calc":["Ser–O–PO₃²⁻(³²P) + H₂O → Ser–OH + Pᵢ(³²P)","³²P **leaves**; ³H **stays**"]},{"text":"Leucine is untouched, so ³H cannot be lost; and removing phosphate must take ³²P with it.","strike":["³H only","Both labels","Neither label"]},{"text":"Answer: ³²P only."}],"trap":"Thinking the phosphatase degrades the whole protein: it removes only phosphate groups."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"³²P in its phosphoserines","note":"label on phosphate"},{"t":"³H in its leucines","note":"label on the protein"},{"t":"protein phosphatase","note":"removes phosphate"}]},{"text":"**Each isotope tags one part.** Phosphorus is only in the phosphate; hydrogen here is in leucine.","fig":"leucine"},{"text":"**Phosphatase = phosphate off.** The phosphate leaves as free Pᵢ.","calc":["phospho-protein + H₂O → protein + Pᵢ"]},{"text":"**Also:** a phosphatase removes only phosphate, so a ¹⁴C label in the sugar backbone stays with the sugar."},{"text":"**Rule to reuse:** a phosphatase removes phosphate groups, so a ³²P label on them leaves while labels elsewhere stay."}]},
  {"id":"cpt-pe1-42b","s":"Atomic & Nuclear Physics","disc":"physics","aamc":"4E","skill":"SIRS 2","from":["pe1-cp:42#2","pe1-cp:42#1"],"q":"Strontium-90 and iodine-131, two fission products in reactor waste, are both β⁻ emitters. Which daughter nuclides do they form?","choices":["Yttrium-90 and xenon-131","Rubidium-90 and tellurium-131","Yttrium-90 and tellurium-131","Krypton-86 and antimony-127"],"ans":0,"exp":"β⁻ decay keeps **A** and raises **Z by 1**. Sr (Z = 38) → **Y (39)**, A stays 90; I (Z = 53) → **Xe (54)**, A stays 131. Rubidium and tellurium lower Z (β⁺), and krypton-86 with antimony-127 lose 4 mass units (α).","how":{"ask":"Apply A unchanged, Z + 1 to each parent, then name the element with the new Z.","know":"• **β⁻ decay**: A unchanged, **Z + 1**.\n• Z sets the element: Kr 36, Rb 37, Sr 38, Y 39; Sb 51, Te 52, I 53, Xe 54.","steps":[{"text":"Both parents are β⁻ emitters: keep A, add 1 to Z.","hl":"both β⁻ emitters","calc":["A → A, Z → Z + 1"]},{"text":"Strontium-90 (Z = 38).","hl":"Strontium-90","calc":["⁹⁰₃₈Sr → ⁹⁰₃₉Y + ⁰₋₁e + ν̄","Z: 38 = 39 + (−1) ✓   A: 90 = 90 ✓"]},{"text":"Iodine-131 (Z = 53).","hl":"iodine-131","calc":["¹³¹₅₃I → ¹³¹₅₄Xe + ⁰₋₁e + ν̄","Z: 53 = 54 + (−1) ✓   A: 131 = 131 ✓"]},{"text":"Rubidium and tellurium have Z − 1 (positron emission); one correct daughter paired with tellurium is still wrong; krypton-86 and antimony-127 are alpha products.","strike":["Rubidium-90 and tellurium-131","Yttrium-90 and tellurium-131","Krypton-86 and antimony-127"]},{"text":"Answer: yttrium-90 and xenon-131."}],"trap":"Moving one step left on the periodic table (rubidium, tellurium): that is β⁺ decay. β⁻ moves one step right."},"teach":[{"text":"First, **find the parents and the decay type**.","marks":[{"t":"Strontium-90","note":"Z = 38, A = 90"},{"t":"iodine-131","note":"Z = 53, A = 131"},{"t":"β⁻ emitters","note":"A same, Z + 1"}]},{"text":"**Keep the mass number.** The emitted electron carries no nucleons.","calc":["daughters: A = 90 and A = 131"]},{"text":"**Step one element to the right.** Z + 1 is the next element in the periodic table.","calc":["Sr (38) → Y (39)","I (53) → Xe (54)"]},{"text":"**Also:** β⁻ decay keeps A the same and raises Z by 1."},{"text":"**Rule to reuse:** for β⁻ decay, keep A and move one element right (Z + 1) to name the daughter."}]},
  {"id":"cpt-pe1-44c","s":"Acids & Bases","disc":"gen_chem","aamc":"5A","skill":"SIRS 2","from":["pe1-cp:44#3","pe1-cp:44#1","pe1-cp:44#2"],"q":"Arsenic acid, H₃AsO₄, is triprotic. Which of these acids dissociates to the smallest extent when dissolved in water?","choices":["HAsO₄²⁻","H₂AsO₄⁻","H₃AsO₄","HCl"],"ans":0,"exp":"HCl is a strong acid. Arsenic acid's three Ka values fall steeply (pKa ≈ 2.2, 7.0, 11.5) because each H⁺ comes off a more negative ion. **HAsO₄²⁻** must lose H⁺ from a 2− ion, so it has the smallest Ka and dissociates least, just as HPO₄²⁻ does in the phosphate series.","how":{"ask":"Rank the four by Ka: the strong acid first, then each successive arsenic-acid step.","know":"• A strong acid (HCl) ionizes completely.\n• Triprotic acid: H₃A → H₂A⁻ → HA²⁻ → A³⁻, with Ka₁ ≫ Ka₂ ≫ Ka₃.\n• The most negative species that still has an H⁺ is the weakest acid.","steps":[{"text":"HCl is a strong acid: it dissociates completely.","strike":["HCl"]},{"text":"Write the three arsenic-acid steps.","hl":"is triprotic","calc":["H₃AsO₄ ⇌ H⁺ + H₂AsO₄⁻   pKa₁ ≈ 2.2","H₂AsO₄⁻ ⇌ H⁺ + HAsO₄²⁻   pKa₂ ≈ 7.0","HAsO₄²⁻ ⇌ H⁺ + AsO₄³⁻   pKa₃ ≈ 11.5"]},{"text":"Each step is about 10⁴–10⁵ times weaker than the one before, because H⁺ leaves an ever more negative ion.","calc":["Ka₁ ≈ 6 × 10⁻³ > Ka₂ ≈ 1 × 10⁻⁷ > Ka₃ ≈ 3 × 10⁻¹²"],"strike":["H₃AsO₄","H₂AsO₄⁻"]},{"text":"Answer: HAsO₄²⁻."}],"trap":"H₃AsO₄ is the weak acid named in the stem, but it is the strongest of the three arsenic species; its ions are weaker still."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"triprotic","note":"three H⁺ to lose"},{"t":"smallest extent","note":"weakest acid, smallest Ka"}]},{"text":"**Strong acids are out:** HCl ionizes completely, so it dissociates most."},{"text":"**Line up the arsenic species by charge:** neutral H₃AsO₄, then 1− H₂AsO₄⁻, then 2− HAsO₄²⁻. The more negative the ion, the more tightly it holds H⁺.","calc":["0 → 1− → 2−","Ka₁ ≫ Ka₂ ≫ Ka₃"]},{"text":"**Also:** HCl and H₂SO₄ (first H⁺) are strong acids; HF, H₃PO₄ and H₂CO₃ are weak."},{"text":"**Also:** each successive Ka of a polyprotic acid is much smaller, because H⁺ is harder to remove from a more negative ion."},{"text":"**Rule to reuse:** in a polyprotic series, the most negative ion that still carries an H⁺ (HPO₄²⁻, HAsO₄²⁻, HCO₃⁻) is the weakest acid."}]},
  {"id":"cpt-pe1-46a","s":"Atomic & Nuclear Physics","disc":"physics","aamc":"4E","skill":"SIRS 1","from":["pe1-cp:46#1"],"q":"Which emission leaves a nucleus with the same mass number A and the same atomic number Z as before?","choices":["A gamma photon","An alpha particle","A beta-minus electron","A positron"],"ans":0,"exp":"A **gamma ray is a photon**: no mass number and no charge, so A and Z stay put. **α** (a ⁴He nucleus) lowers A by 4 and Z by 2; **β⁻** (an electron) raises Z by 1; **β⁺** (a positron) lowers Z by 1.","how":{"ask":"For each emission, write what it carries away in A and Z; find the one that carries away zero of both.","know":"• **α** = ⁴₂He: A − 4, Z − 2.\n• **β⁻** = electron (⁰₋₁e): Z + 1, A same.\n• **β⁺** = positron (⁰₊₁e): Z − 1, A same.\n• **γ** = high-energy photon (⁰₀γ): A and Z unchanged; the nucleus just drops from an excited state.","steps":[{"text":"Alpha decay removes two protons and two neutrons.","calc":["²²²₈₆Rn → ²¹⁸₈₄Po + ⁴₂He","A: 222 → 218, Z: 86 → 84"],"strike":["An alpha particle"]},{"text":"Beta decays keep A but change Z by one.","calc":["β⁻: ³₁H → ³₂He + ⁰₋₁e (Z + 1)","β⁺: ¹⁸₉F → ¹⁸₈O + ⁰₊₁e (Z − 1)"],"strike":["A beta-minus electron","A positron"]},{"text":"Gamma emission carries away energy only.","hl":"the same mass number A and the same atomic number Z","calc":["¹³⁷ᵐ₅₆Ba → ¹³⁷₅₆Ba + ⁰₀γ","A: 137 → 137, Z: 56 → 56"]},{"text":"Answer: a gamma photon."}],"trap":"Choosing the positron or electron because A is unchanged. Beta particles carry charge, so Z changes by one."},"teach":[{"text":"First, **find what must stay the same**.","marks":[{"t":"mass number A","note":"protons + neutrons"},{"t":"atomic number Z","note":"protons: the element"}]},{"text":"**Track A and Z for each emission.**","calc":["α (⁴He): A − 4, Z − 2","β⁻ (electron): Z + 1","β⁺ (positron): Z − 1","γ (photon): no change"]},{"text":"**A gamma ray is light.** An excited nucleus releases its extra energy as a photon, like an excited atom emitting light.","calc":["X* → X + γ"]},{"text":"**Rule to reuse:** gamma decay emits a photon and changes neither A nor Z; α is ⁴He, β⁻ is an electron, β⁺ is a positron."}]},
  {"id":"cpt-pe1-47c","s":"Thermodynamics & Kinetics","disc":"gen_chem","aamc":"5E","skill":"SIRS 1","from":["pe1-cp:47#3","pe1-cp:47#1","pe1-cp:47#2"],"q":"A reaction that releases a gas is spontaneous only above a certain temperature. Which signs of ΔH and ΔS fit ΔG = ΔH − TΔS?","choices":["ΔH positive, ΔS positive","ΔH negative, ΔS negative","ΔH negative, ΔS positive","ΔH positive, ΔS negative"],"ans":0,"exp":"Spontaneous means **ΔG < 0**, with **ΔG = ΔH − TΔS**. Releasing a gas raises entropy, so **ΔS > 0** and the −TΔS term grows more negative as T rises. Being nonspontaneous at low T, where ΔG ≈ ΔH, requires **ΔH > 0**. ΔH < 0 with ΔS > 0 would be spontaneous at every temperature; ΔH > 0 with ΔS < 0 at none; both negative only at low T.","how":{"ask":"Which sign pair makes ΔG positive at low T but negative at high T?","know":"• **ΔG = ΔH − TΔS**; spontaneous when ΔG < 0.\n• At low T the ΔH term decides; at high T the −TΔS term decides.\n• A gas formed → **ΔS > 0**.\n• ΔH −, ΔS + → always; ΔH +, ΔS − → never; both + → high T only; both − → low T only.","steps":[{"text":"A gas is released, so entropy rises.","hl":"releases a gas","calc":["gas formed → ΔS > 0","−TΔS < 0, larger as T rises"]},{"text":"Not spontaneous at low T means ΔG > 0 there, where ΔG ≈ ΔH; at high T the −TΔS term wins.","hl":"spontaneous only above a certain temperature","calc":["low T: ΔG ≈ ΔH > 0 → ΔH > 0","high T: TΔS > ΔH → ΔG < 0"]},{"text":"A negative ΔH with a positive ΔS gives ΔG < 0 at every temperature, so there is no threshold.","calc":["ΔG = (−) − T(+) < 0 at all T"],"strike":["ΔH negative, ΔS positive"]},{"text":"A negative ΔS contradicts the gas release: with ΔH positive it is never spontaneous, and with ΔH negative it is spontaneous only below some temperature.","calc":["(+) − T(−) > 0 at all T","(−) − T(−) < 0 only at low T"],"strike":["ΔH positive, ΔS negative","ΔH negative, ΔS negative"]},{"text":"Answer: ΔH positive, ΔS positive."}],"trap":"Choosing ΔH negative with ΔS positive because both terms favor spontaneity: that pair is spontaneous at every temperature, with no threshold to cross."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"releases a gas","note":"ΔS > 0"},{"t":"only above a certain temperature","note":"ΔG < 0 at high T only"},{"t":"ΔG = ΔH − TΔS","note":"the sign test"}]},{"text":"**ΔG = ΔH − TΔS.** At low T the ΔH term dominates; as T rises, the −TΔS term takes over."},{"text":"**Four sign pairs.**","calc":["ΔH −, ΔS +: always spontaneous","ΔH +, ΔS −: never spontaneous","ΔH +, ΔS +: spontaneous above some T","ΔH −, ΔS −: spontaneous below some T"]},{"text":"**Also:** spontaneous means ΔG < 0, however slow the reaction."},{"text":"**Also:** a reaction that makes gas from a solid or solution has ΔS > 0."},{"text":"**Rule to reuse:** by ΔG = ΔH − TΔS, a reaction that is spontaneous only at high temperature has both ΔH and ΔS positive."}]},
  {"id":"cpt-pe1-48a","s":"Thermodynamics & Kinetics","disc":"gen_chem","aamc":"4E","skill":"SIRS 1","from":["pe1-cp:48#1","pe1-cp:48#2"],"q":"Chlorine atoms destroy ozone in two steps: Cl + O₃ → ClO + O₂, then ClO + O → Cl + O₂. What is the overall reaction?","choices":["O₃ + O → 2O₂","Cl + O₃ + O → Cl + 2O₂","O₃ + ClO → Cl + 2O₂","2O₃ → 3O₂"],"ans":0,"exp":"Add the two steps and cross out anything on both sides: Cl + O₃ + ClO + O → ClO + O₂ + Cl + O₂ becomes **O₃ + O → 2O₂**. Cl is used and then regenerated (a catalyst), and ClO is made and then used (an intermediate), so neither appears overall. Leaving Cl on both sides is an unfinished sum; O₃ + ClO → Cl + 2O₂ drops the O-atom reactant and leaves ClO, an intermediate, uncancelled; 2O₃ → 3O₂ is a different net reaction.","how":{"ask":"Add the steps, then cancel each species that appears on both sides.","know":"• **Overall reaction** = sum of the elementary steps (multiply a step if needed so shared species cancel).\n• Cancel species found on both sides: **catalysts** (used, then regenerated) and **intermediates** (made, then used).\n• What's left holds only the true reactants and products.","steps":[{"text":"Write both steps and add them.","hl":"Cl + O₃ → ClO + O₂, then ClO + O → Cl + O₂","calc":["Cl + O₃ → ClO + O₂","ClO + O → Cl + O₂","sum: Cl + O₃ + ClO + O → ClO + O₂ + Cl + O₂"]},{"text":"Cancel Cl and ClO, each found on both sides, and combine the O₂.","calc":["cancel Cl (left and right)","cancel ClO (left and right)","**O₃ + O → 2O₂**"]},{"text":"Leaving Cl on both sides is a sum that was never simplified.","strike":["Cl + O₃ + O → Cl + 2O₂"]},{"text":"O₃ + ClO → Cl + 2O₂ drops the O-atom reactant and leaves ClO, an intermediate, uncancelled.","strike":["O₃ + ClO → Cl + 2O₂"]},{"text":"2O₃ → 3O₂ is balanced, but it uses no free O atom, so it is not the sum of these steps.","strike":["2O₃ → 3O₂"]},{"text":"Answer: O₃ + O → 2O₂."}],"trap":"Cl + O₃ + O → Cl + 2O₂ is balanced and looks complete, but a species on both sides must be cancelled; an overall equation never shows a catalyst."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"two steps","note":"a mechanism"},{"t":"Cl + O₃ → ClO + O₂","note":"step one"},{"t":"ClO + O → Cl + O₂","note":"step two"},{"t":"overall reaction","note":"sum and cancel"}]},{"text":"**A mechanism** is the list of elementary steps a reaction actually goes through. Adding them gives the overall equation."},{"text":"**Cancel like terms**, just as in algebra: a species on both sides drops out.","calc":["A + B → C","C + D → A + E","sum: B + D → E"]},{"text":"**Also:** after summing a mechanism, confirm that atoms and total charge (coefficient × charge) balance on both sides."},{"text":"**Rule to reuse:** add the steps, then cancel every species on both sides (catalysts and intermediates) to get the overall reaction."}]},
  {"id":"cpt-pe1-48c","s":"Thermodynamics & Kinetics","disc":"gen_chem","aamc":"4E","skill":"SIRS 1","from":["pe1-cp:48#3"],"q":"A little FeSO₄ (Fe²⁺) speeds up the oxidation of iodide by persulfate: S₂O₈²⁻ + 2Fe²⁺ → 2SO₄²⁻ + 2Fe³⁺, then 2Fe³⁺ + 2I⁻ → 2Fe²⁺ + I₂. Which species is the catalyst?","choices":["Fe²⁺","Fe³⁺","I⁻","SO₄²⁻"],"ans":0,"exp":"**Fe²⁺ is used in the first step and regenerated in the second**, so it is the catalyst: present at the start and given back at the end. **Fe³⁺ is made in the first step and used up in the second**: an intermediate. I⁻ is a reactant and SO₄²⁻ a product; neither cancels. Overall: S₂O₈²⁻ + 2I⁻ → 2SO₄²⁻ + I₂.","how":{"ask":"For each iron ion, is it consumed first and returned later, or made first and consumed later?","know":"• **Catalyst**: consumed in an early step, **regenerated** later; it is present before the reaction starts.\n• **Intermediate**: **produced** in an early step, consumed later; it is never added at the start.\n• Both cancel from the overall equation; reactants and products do not.","steps":[{"text":"Track Fe²⁺: a reactant in step one, a product in step two.","hl":"S₂O₈²⁻ + 2Fe²⁺ → 2SO₄²⁻ + 2Fe³⁺","calc":["step one: 2Fe²⁺ used","step two: 2Fe²⁺ made → **regenerated** → catalyst"]},{"text":"Track Fe³⁺: made in step one, used up in step two, so it is an intermediate.","hl":"2Fe³⁺ + 2I⁻ → 2Fe²⁺ + I₂","strike":["Fe³⁺"]},{"text":"I⁻ is only consumed and SO₄²⁻ only produced: a reactant and a product, which stay in the overall equation.","calc":["overall: S₂O₈²⁻ + 2I⁻ → 2SO₄²⁻ + I₂"],"strike":["I⁻","SO₄²⁻"]},{"text":"Answer: Fe²⁺."}],"trap":"Fe³⁺ also cancels from the overall equation, but it is made first and used later: that is an intermediate. A catalyst enters first as a reactant and is given back."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"A little FeSO₄ (Fe²⁺)","note":"added at the start"},{"t":"S₂O₈²⁻ + 2Fe²⁺","note":"step one reactants"},{"t":"2Fe²⁺ + I₂","note":"step two products"}]},{"text":"**Catalyst: in, then out.** It enters an early step as a reactant and leaves a later step as a product, unchanged overall."},{"text":"**Intermediate: out, then in.** It is made in an early step and used up in a later one.","calc":["catalyst: reactant (step one) → product (step two)","intermediate: product (step one) → reactant (step two)"]},{"text":"**Rule to reuse:** a catalyst is used and then regenerated; an intermediate is made and then used up. Both cancel from the overall equation."}]},
  {"id":"cpt-pe1-49b","s":"Electrochemistry & Redox","disc":"gen_chem","aamc":"5E","skill":"SIRS 2","from":["pe1-cp:49#2","pe1-cp:49#1","pe1-cp:49#3"],"q":"A catalytic converter treats exhaust containing carbon monoxide and unburned propane. Taken together, which products does it form from these pollutants?","choices":["CO₂ and H₂O","CO and H₂","CH₃OH and H₂","C and H₂O"],"ans":0,"exp":"The converter **oxidizes** with O₂: carbon monoxide goes to **CO₂** (carbon +2 → +4), and a hydrocarbon such as propane burns completely to **CO₂ and H₂O**. Soot, CO, methanol or H₂ would be incomplete or reductive products.","how":{"ask":"What do CO and a hydrocarbon become when fully oxidized by O₂ over the catalyst?","know":"• The converter's oxidation job: **CO → CO₂** and **hydrocarbons → CO₂ + H₂O**.\n• Oxidation of carbon raises its oxidation number; full oxidation of carbon ends at +4 (CO₂).","steps":[{"text":"Note the two pollutants.","hl":"carbon monoxide and unburned propane","calc":["CO and C₃H₈"]},{"text":"Oxidize each with O₂ and balance.","calc":["2CO + O₂ → 2CO₂   (C: +2 → +4)","C₃H₈ + 5O₂ → 3CO₂ + 4H₂O"]},{"text":"CO and H₂, or soot and water, are incomplete products: carbon not taken all the way to +4 and H₂ not oxidized; the converter oxidizes fully to CO₂ and H₂O.","strike":["CO and H₂","C and H₂O"]},{"text":"Methanol plus H₂ is a partial, not complete, oxidation and is not what leaves the tailpipe.","strike":["CH₃OH and H₂"]},{"text":"Answer: CO₂ and H₂O."}],"trap":"Forgetting the hydrogen in a hydrocarbon: complete oxidation gives water as well as carbon dioxide."},"teach":[{"text":"First, **find the pollutants**.","marks":[{"t":"carbon monoxide","note":"CO, C = +2"},{"t":"unburned propane","note":"hydrocarbon C₃H₈"}]},{"text":"**Oxidation side of the converter:** O₂ in the exhaust finishes burning anything carbon-based.","calc":["CO → CO₂","CₓHᵧ → CO₂ + H₂O"]},{"text":"**Check by oxidation number:** carbon in CO is +2 and in CO₂ is +4, so carbon loses electrons: oxidation."},{"text":"**Also:** a solid catalyst acting on gases (a catalytic converter) is a heterogeneous catalyst."},{"text":"**Also:** a catalytic converter reduces nitrogen oxides (NOₓ) to N₂ while it oxidizes CO and hydrocarbons."},{"text":"**Rule to reuse:** a catalytic converter oxidizes CO to CO₂ and unburned hydrocarbons to CO₂ and H₂O."}]},
  {"id":"cpt-pe1-51a","s":"Thermodynamics & Kinetics","disc":"gen_chem","aamc":"5E","skill":"SIRS 3","from":["pe1-cp:51#1","pe1-cp:51#2","pe1-cp:51#3"],"q":"Equal masses of manganese dioxide catalyst, one as a single pellet and one as fine powder, are added to identical hydrogen peroxide solutions. Why does the powder release O₂ faster?","choices":["More exposed surface","Greater catalyst mass","Higher activation energy","Larger equilibrium constant"],"ans":0,"exp":"A solid catalyst works only at its **surface**, where H₂O₂ molecules meet it. Powder exposes far **more surface area** for the same mass, so more reaction sites act at once and the **rate rises**. The mass is equal, a catalyst lowers (not raises) Ea, and catalysts don't change K.","how":{"ask":"What differs between the pellet and the powder, given that their masses match?","know":"• A **heterogeneous catalyst reacts at its surface**.\n• Breaking a solid into small pieces greatly **raises surface area** without changing mass.\n• More surface → more active sites → **faster rate**.","steps":[{"text":"Note what is the same and what differs.","hl":"Equal masses of manganese dioxide catalyst","calc":["mass: same","form: pellet vs fine powder"]},{"text":"The masses are equal, so mass can't explain the difference.","strike":["Greater catalyst mass"]},{"text":"Powder exposes more surface where H₂O₂ meets the catalyst, so more molecules react per second.","calc":["surface area ↑ → active sites ↑ → rate ↑"]},{"text":"A catalyst lowers Ea, and a higher Ea would slow the reaction; neither form changes K.","strike":["Higher activation energy","Larger equilibrium constant"]},{"text":"Answer: more exposed surface."}],"trap":"Thinking grinding adds catalyst: the amount is unchanged; only the surface the reactants can reach grows."},"teach":[{"text":"First, **find what was changed**.","marks":[{"t":"Equal masses","note":"mass held fixed"},{"t":"fine powder","note":"more surface"},{"t":"release O₂ faster","note":"rate"}]},{"text":"**Surface catalysis:** reactant molecules must touch the solid to react, so only surface atoms count."},{"text":"**Smaller pieces, more surface.** Cutting a solid exposes new faces that were inside before.","calc":["particle size ↓ → surface area ↑ → rate ↑"]},{"text":"**Also:** grinding or cutting a catalyst raises its surface area but leaves its mass unchanged."},{"text":"**Also:** cutting a cube into smaller cubes multiplies the total surface area by the ratio of the edge lengths."},{"text":"**Rule to reuse:** grinding a solid catalyst speeds the reaction because it exposes more surface area."}]},
  {"id":"cpt-pe1-52a","s":"Electricity & Magnetism","disc":"physics","aamc":"4C","skill":"SIRS 3","from":["pe1-cp:52#1","pe1-cp:52#2","pe1-cp:52#3"],"q":"A 9.0-V battery powers a 30-Ω heater coil. Which replacement coil would draw the largest current from the battery?","choices":["A 12-Ω coil","A 45-Ω coil","A 60-Ω coil","A 90-Ω coil"],"ans":0,"exp":"By **Ohm's law, I = V/R**, a fixed battery voltage drives more current through a smaller resistance. The 12-Ω coil draws 9.0 V ÷ 12 Ω = **0.75 A**, more than the 0.30 A now.","how":{"ask":"With the battery voltage fixed, which resistance gives the biggest I = V/R?","know":"• **Ohm's law: I = V/R**.\n• Fixed V → current is **inversely proportional** to resistance: lower R, more current.","steps":[{"text":"The battery sets V; only R changes.","hl":"A 9.0-V battery","calc":["I = V ÷ R"]},{"text":"Current now.","hl":"30-Ω heater coil","calc":["I = 9.0 V ÷ 30 Ω = **0.30 A**"]},{"text":"Compare the replacements.","calc":["12 Ω: 9.0 ÷ 12 = **0.75 A**","45 Ω: 9.0 ÷ 45 = 0.20 A","60 Ω: 9.0 ÷ 60 = 0.15 A","90 Ω: 9.0 ÷ 90 = 0.10 A"]},{"text":"The larger coils all lower the current below 0.30 A.","strike":["A 45-Ω coil","A 60-Ω coil","A 90-Ω coil"]},{"text":"Answer: the 12-Ω coil."}],"trap":"Thinking a bigger resistor \"uses more\" current. At fixed voltage, more resistance means less current."},"teach":[{"text":"First, **find the givens**.","marks":[{"t":"9.0-V battery","note":"V fixed"},{"t":"30-Ω heater coil","note":"R now"},{"t":"largest current","note":"goal"}]},{"text":"**Ohm's law:** the battery's push divided by the resistance gives the current.","calc":["I = V ÷ R"]},{"text":"**Smaller R, bigger I.** Halve R and the current doubles.","calc":["R ↓ → I ↑"]},{"text":"**Also:** a longer, thinner or hotter metal wire has more resistance; shorter, thicker or cooler has less."},{"text":"**Also:** lowering the ion concentrations a cell runs on lowers its voltage, and at fixed R that lowers the current."},{"text":"**Rule to reuse:** to raise the current from a fixed voltage, lower the resistance (I = V/R)."}]},
  {"id":"cpt-pe1-53a","s":"Electrochemistry & Redox","disc":"gen_chem","aamc":"4C","skill":"SIRS 2","from":["pe1-cp:53#1"],"q":"Standard reduction potentials: Mg²⁺/Mg, −2.37 V; Ag⁺/Ag, +0.80 V. Strips of magnesium and silver are each dropped into 1 M HCl. Which produces H₂ gas?","choices":["Magnesium only","Silver only","Both magnesium and silver","Neither metal"],"ans":0,"exp":"H⁺/H₂ is the **zero reference**. Magnesium's E° is **negative** (−2.37 V), so Mg is more easily oxidized than H₂: Mg → Mg²⁺ while **H⁺ gains electrons and becomes H₂**. Silver's E° is **positive**, so Ag holds its electrons and does not reduce H⁺; no gas forms on it.","how":{"ask":"For each metal, is it easier to oxidize than H₂ (E° below that of H⁺/H₂)?","know":"• Reference: **2H⁺ + 2e⁻ → H₂, E° = 0 V**.\n• Metal with **E° < 0** is oxidized by H⁺: M → Mⁿ⁺ and H⁺ → H₂.\n• Metal with **E° > 0** does not react with H⁺.","steps":[{"text":"Note both potentials.","hl":"Mg²⁺/Mg, −2.37 V","calc":["Mg: −2.37 V","Ag: +0.80 V","H⁺/H₂: 0 V"]},{"text":"Magnesium: E° < 0, so Mg is easier to oxidize than H₂ and reduces H⁺.","calc":["Mg + 2H⁺ → Mg²⁺ + H₂"]},{"text":"E° > 0: silver is harder to oxidize than H₂, so it cannot reduce H⁺.","strike":["Silver only","Both magnesium and silver"]},{"text":"Magnesium does react, so it is not the case that neither metal gives gas.","strike":["Neither metal"]},{"text":"Answer: magnesium only."}],"trap":"Thinking any metal dissolves in acid: only metals with E° below 0 V (more active than H₂) reduce H⁺ to H₂."},"teach":[{"text":"First, **find the potentials**.","marks":[{"t":"−2.37 V","note":"Mg: below 0"},{"t":"+0.80 V","note":"Ag: above 0"},{"t":"1 M HCl","note":"source of H⁺"},{"t":"H₂ gas","note":"H⁺ must be reduced"}]},{"text":"**H⁺/H₂ sits at 0 V.** A metal below it gives electrons to H⁺; a metal above it doesn't.","calc":["E°(metal) < 0 → metal oxidized, H⁺ → H₂"]},{"text":"**Rule to reuse:** a metal more easily oxidized than H₂ (E° < 0) is oxidized by acid and H⁺ is reduced to H₂ gas."}]},
  {"id":"cpt-pe1-54a","s":"Electrochemistry & Redox","disc":"gen_chem","aamc":"4E","skill":"SIRS 2","from":["pe1-cp:54#1","pe1-cp:54#2"],"q":"Standard reduction potentials: Fe²⁺/Fe, −0.44 V; Ni²⁺/Ni, −0.25 V. An iron nail is placed in nickel(II) sulfate solution. Which species is oxidized?","choices":["Iron metal","Nickel metal","Iron(II) ions","Nickel(II) ions"],"ans":0,"exp":"The half-reaction with the **lower reduction potential runs backward** as oxidation. Iron's E° (−0.44 V) is lower than nickel's (−0.25 V), so **Fe → Fe²⁺ + 2e⁻**, and Ni²⁺ is reduced to nickel metal.","how":{"ask":"Which half-reaction has the lower E°, and so runs as an oxidation?","know":"• **Higher E°** → reduced (cathode). **Lower E°** → oxidized (anode).\n• Only the reduced form of a couple (the metal) can be oxidized; the ion is already oxidized.","steps":[{"text":"Compare the two potentials.","hl":"Fe²⁺/Fe, −0.44 V","calc":["Fe²⁺/Fe: −0.44 V (lower)","Ni²⁺/Ni: −0.25 V (higher)"]},{"text":"Lower E° is oxidized: iron metal gives up electrons.","calc":["Fe → Fe²⁺ + 2e⁻"]},{"text":"Nickel(II) ions are reduced, not oxidized; nickel metal is the product they form.","calc":["Ni²⁺ + 2e⁻ → Ni"],"strike":["Nickel(II) ions","Nickel metal"]},{"text":"Fe²⁺ is the product of the oxidation, not the species being oxidized.","strike":["Iron(II) ions"]},{"text":"Answer: iron metal."}],"trap":"Picking the ion of the more negative couple: Fe²⁺ is what iron becomes, not what gets oxidized."},"teach":[{"text":"First, **find the potentials**.","marks":[{"t":"−0.44 V","note":"Fe: lower"},{"t":"−0.25 V","note":"Ni: higher"},{"t":"iron nail","note":"Fe metal"},{"t":"nickel(II) sulfate","note":"Ni²⁺ ions"}]},{"text":"**Higher E° wins the electrons.** Ni²⁺ has the higher E°, so it is reduced."},{"text":"**The other one is oxidized.** Iron's half-reaction runs in reverse.","calc":["Fe → Fe²⁺ + 2e⁻","Ni²⁺ + 2e⁻ → Ni"]},{"text":"**Also:** balance a redox equation by multiplying the half-reactions so the electrons lost equal the electrons gained, then check the charge."},{"text":"**Rule to reuse:** of two half-reactions, the metal with the lower reduction potential is oxidized."}]},
  {"id":"cpt-pe1-55a","s":"Electrochemistry & Redox","disc":"gen_chem","aamc":"4C","skill":"SIRS 2","from":["pe1-cp:55#1","pe1-cp:55#2","pe1-cp:55#3"],"q":"In a galvanic cell, copper is the cathode (E° = +0.34 V) and iron is the anode (E° = −0.44 V). What is E°cell?","choices":["+0.78 V","−0.10 V","+0.34 V","+0.44 V"],"ans":0,"exp":"Subtract the anode from the cathode, **E°cell = E°red(cathode) − E°red(anode)**, using both reduction potentials: +0.34 − (−0.44) = **+0.78 V**. Adding the two values gives −0.10 V, and either electrode alone (+0.34 V or +0.44 V) is only half the cell.","how":{"ask":"Subtract the anode's reduction potential from the cathode's.","know":"• **E°cell = E°cathode − E°anode** (both as reduction potentials from the table).\n• Don't flip a sign and then also subtract; do one or the other.","steps":[{"text":"Note which electrode is which.","hl":"copper is the cathode (E° = +0.34 V)","calc":["E°cathode = +0.34 V","E°anode = −0.44 V"]},{"text":"Apply the formula.","calc":["E°cell = E°cathode − E°anode","E°cell = +0.34 − (−0.44)","E°cell = +0.34 + 0.44 = **+0.78 V**"]},{"text":"Adding the two tabulated potentials skips the anode's sign change.","calc":["+0.34 + (−0.44) = −0.10 V ✗"],"strike":["−0.10 V"]},{"text":"+0.34 V is the cathode alone, and +0.44 V is only the anode's oxidation potential; the cell needs both.","calc":["oxidation of Fe: +0.44 V","reduction of Cu²⁺: +0.34 V","sum = +0.78 V"],"strike":["+0.34 V","+0.44 V"]},{"text":"Answer: +0.78 V."}],"trap":"Adding the two tabulated reduction potentials: that skips the sign change for the anode's oxidation."},"teach":[{"text":"First, **find the roles and values**.","marks":[{"t":"copper is the cathode","note":"reduction"},{"t":"+0.34 V","note":"E°cathode"},{"t":"iron is the anode","note":"oxidation"},{"t":"−0.44 V","note":"E°anode"}]},{"text":"**The formula** uses both reduction potentials as listed.","calc":["E°cell = E°cathode − E°anode"]},{"text":"**Watch the double negative.** Subtracting a negative number adds it.","calc":["+0.34 − (−0.44) = +0.34 + 0.44"]},{"text":"**Also:** in a galvanic cell, the cathode is the half-cell with the higher standard reduction potential."},{"text":"**Also:** a positive E°cell means spontaneous as written; a negative E°cell means not spontaneous (the reverse reaction is)."},{"text":"**Rule to reuse:** E°cell = E°cathode − E°anode, with both values taken as reduction potentials."}]},
  {"id":"cpt-pe1-57a","s":"Equilibrium","disc":"gen_chem","aamc":"5A","skill":"SIRS 2","from":["pe1-cp:57#1","pe1-cp:57#2","pe1-cp:57#3"],"q":"Solid sodium chloride is dissolved in a saturated silver chloride solution that sits over undissolved AgCl. Immediately afterward, how does the ion product Q compare with Ksp?","choices":["Above Ksp","Below Ksp","Equal to Ksp","Exactly zero"],"ans":0,"exp":"Before the addition the solution is saturated, so **Q = [Ag⁺][Cl⁻] = Ksp**. NaCl adds **Cl⁻, a common ion**, raising [Cl⁻] while [Ag⁺] is momentarily unchanged, so the product **Q now exceeds Ksp**.","how":{"ask":"What was Q before the addition, and which factor in Q just grew?","know":"• **Q = [Ag⁺][Cl⁻]** at any moment; **Ksp** is its value at saturation.\n• Saturated: Q = Ksp. Adding a **common ion** raises one factor of Q.\n• Q > Ksp → precipitate forms; Q < Ksp → more dissolves.","steps":[{"text":"Start from the saturated solution.","hl":"saturated silver chloride solution","calc":["AgCl(s) ⇌ Ag⁺ + Cl⁻","Q = [Ag⁺][Cl⁻] = Ksp = 1.8 × 10⁻¹⁰","[Ag⁺] = [Cl⁻] = √(1.8 × 10⁻¹⁰) = 1.34 × 10⁻⁵ M"]},{"text":"NaCl adds Cl⁻. Suppose [Cl⁻] becomes 0.050 M.","hl":"Solid sodium chloride","calc":["Q = (1.34 × 10⁻⁵)(0.050)","Q = 6.7 × 10⁻⁷ > 1.8 × 10⁻¹⁰"]},{"text":"Raising one factor can't leave Q equal to or below Ksp.","strike":["Below Ksp","Equal to Ksp"]},{"text":"Ag⁺ is still present, so Q is not zero.","strike":["Exactly zero"]},{"text":"Answer: Q is above Ksp."}],"trap":"Thinking Q stays at Ksp because the solution was saturated: saturation describes the moment before the common ion arrived."},"teach":[{"text":"First, **find the key words**.","marks":[{"t":"sodium chloride","note":"adds Cl⁻, a common ion"},{"t":"saturated","note":"Q = Ksp before"},{"t":"Immediately afterward","note":"before any shift"}]},{"text":"**Q has the same form as Ksp** but uses the concentrations right now.","calc":["Q = [Ag⁺][Cl⁻]"]},{"text":"**One factor up → Q up.** From Q = Ksp, any extra common ion pushes Q above Ksp.","calc":["[Cl⁻] ↑ → Q ↑ → Q > Ksp"]},{"text":"**Also:** a common ion shifts a saturated salt's equilibrium left, so the sparingly soluble salt precipitates."},{"text":"**Also:** adding a common ion lowers a salt's solubility, but Ksp itself doesn't change unless temperature does."},{"text":"**Rule to reuse:** adding a common ion to a saturated solution raises Q above Ksp."}]},
  {"id":"cpt-pe1-58a","s":"Stoichiometry & Solutions","disc":"gen_chem","aamc":"5A","skill":"SIRS 2","from":["pe1-cp:58#1"],"q":"A recipe needs 2.34 g of sodium chloride (molar mass 58.5 g/mol), measured out from a 0.400 M NaCl stock. What volume of stock is required?","choices":["100 mL","16 mL","40 mL","5.85 L"],"ans":0,"exp":"First grams to moles: 2.34 g ÷ 58.5 g/mol = **0.0400 mol**. Then **V = n ÷ M** = 0.0400 mol ÷ 0.400 mol/L = 0.100 L = **100 mL**.","how":{"ask":"Convert grams to moles, then divide moles by molarity to get litres, then convert to mL.","know":"• **n = mass ÷ molar mass**.\n• **M = n ÷ V**, so **V = n ÷ M** (V in litres).\n• 1 L = 1000 mL.","steps":[{"text":"Note the mass, molar mass and molarity.","hl":"2.34 g of sodium chloride","calc":["m = 2.34 g","molar mass = 58.5 g/mol","M = 0.400 mol/L"]},{"text":"Grams to moles.","calc":["n = 2.34 g ÷ 58.5 g/mol","n = 0.0400 mol"]},{"text":"Volume from V = n ÷ M, then mL.","calc":["V = 0.0400 mol ÷ 0.400 mol/L","V = 0.100 L","V = 0.100 × 1000 = **100 mL**"]},{"text":"Multiplying n × M instead of dividing gives 16 mL, and stopping at the moles (0.0400 read as litres) gives 40 mL.","calc":["0.0400 × 0.400 = 0.016 L = 16 mL ✗","0.0400 → 40 mL skips ÷ M ✗"],"strike":["16 mL","40 mL"]},{"text":"Skipping the grams-to-moles step divides grams by molarity.","calc":["2.34 ÷ 0.400 = 5.85 ✗"],"strike":["5.85 L"]},{"text":"Answer: 100 mL."}],"trap":"Dividing grams by molarity: molarity is moles per litre, so the mass must become moles first."},"teach":[{"text":"First, **find the givens**.","marks":[{"t":"2.34 g","note":"mass"},{"t":"58.5 g/mol","note":"molar mass"},{"t":"0.400 M","note":"mol per L"}]},{"text":"**Grams → moles.**","calc":["n = mass ÷ molar mass"]},{"text":"**Moles → litres → mL.** Rearrange M = n/V.","calc":["V = n ÷ M","mL = L × 1000"]},{"text":"**Rule to reuse:** V = n ÷ M gives litres; convert grams to moles first and litres to mL at the end."}]},
  {"id":"cpt-pe1-59c","s":"Mechanics & Energy","disc":"physics","aamc":"4A","skill":"SIRS 1","from":["pe1-cp:59#3","pe1-cp:59#1","pe1-cp:59#2"],"q":"A rehab patient pushes a weighted sled with a steady 120-N force through 15 m in 6.0 s. What average power does the patient deliver?","choices":["300 W","1800 W","48 W","20 W"],"ans":0,"exp":"**Power = force × distance ÷ time**: W = 120 N × 15 m = 1800 J, and P = 1800 J ÷ 6.0 s = **300 W**. N·m/s = J/s = W.","how":{"ask":"Find the work as force × distance, then divide by the time.","know":"• **Work W = F·d** (N·m = J) when force and motion are in the same direction.\n• **Power P = W/t = F·d/t** (J/s = W).\n• Equivalently P = F·v.","steps":[{"text":"Work done on the sled.","hl":"a steady 120-N force through 15 m","calc":["W = F × d = 120 N × 15 m","W = **1800 J**"]},{"text":"Divide by the time.","hl":"6.0 s","calc":["P = W ÷ t = 1800 J ÷ 6.0 s","P = **300 W**","check: v = 15 m ÷ 6.0 s = 2.5 m/s; F·v = 120 × 2.5 = 300 W"]},{"text":"1800 W is the work in joules, never divided by time. 48 W uses F × t ÷ d (120 × 6.0 ÷ 15). 20 W uses F ÷ t and ignores the distance.","strike":["1800 W","48 W","20 W"]},{"text":"Answer: 300 W."}],"trap":"Stopping at force × distance: 1800 J is energy. Power needs the division by time."},"teach":[{"text":"First, **find every number**.","marks":[{"t":"120-N force","note":"F"},{"t":"15 m","note":"distance d"},{"t":"6.0 s","note":"time t"}]},{"text":"**Force × distance is work (energy).**","calc":["N·m = J","120 × 15 = 1800 J"]},{"text":"**Work ÷ time is power.**","calc":["J ÷ s = W","1800 ÷ 6.0 = 300 W"]},{"text":"**Also:** W = J/s = kg·m²·s⁻³; one more s⁻¹ than a joule means power."},{"text":"**Also:** kg·m²·s⁻² is a joule (energy), not power; power needs kg·m²·s⁻³."},{"text":"**Rule to reuse:** force × distance ÷ time is power (N·m/s = J/s = W); force × distance alone is energy."}]},
];
